// v3ra01_render_triggers / ex1 - reference solution.
import { useState } from "react";

const MAX_LEVEL = 5;

export function LevelMeter({ onRender }: { onRender: () => void }) {
  onRender();

  const [level, setLevel] = useState(1);

  // The clamp lives inside the updater, so at the cap the value handed back is
  // the value React already holds. Object.is says they are equal and React
  // discards the update instead of scheduling a render.
  const raise = () => setLevel((current) => Math.min(current + 1, MAX_LEVEL));

  return (
    <>
      <p role="status">Level: {level}</p>
      <button type="button" onClick={raise}>
        Raise
      </button>
    </>
  );
}

// v3ra01_render_triggers / ex2 - reference solution.
import { useState } from "react";

export function TagEditor() {
  const [tags, setTags] = useState<string[]>([]);
  const [draft, setDraft] = useState("");

  const add = () => {
    const next = draft.trim();
    if (next === "") return;
    // A brand-new array: the reference differs, so React schedules a render.
    setTags((current) => [...current, next]);
    setDraft("");
  };

  return (
    <>
      <label htmlFor="new-tag">New tag</label>
      <input
        id="new-tag"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
      />
      <button type="button" onClick={add}>
        Add tag
      </button>
      <p role="status">Tags: {tags.length}</p>
      <ul>
        {tags.map((tag, index) => (
          <li key={`${tag}-${index}`}>{tag}</li>
        ))}
      </ul>
    </>
  );
}

// v3ra01_render_triggers / ex3 - reference solution.
import { useState } from "react";
import type { ReactNode } from "react";

function HeavyReport({ onRender }: { onRender: () => void }) {
  onRender();
  return <h2>Quarterly report</h2>;
}

export function ReportShell({ children }: { children: ReactNode }) {
  const [ticks, setTicks] = useState(0);

  return (
    <>
      <p role="status">Ticks: {ticks}</p>
      <button type="button" onClick={() => setTicks((n) => n + 1)}>
        Tick
      </button>
      {children}
    </>
  );
}

export function ReportPage({ onReportRender }: { onReportRender: () => void }) {
  // ReportPage holds no state, so it never re-renders, so this element object
  // is created once and passed down unchanged. Reconciliation sees the same
  // reference in the same position and skips the subtree - no memo required.
  return (
    <ReportShell>
      <HeavyReport onRender={onReportRender} />
    </ReportShell>
  );
}

// v3ra01_render_triggers / ex4 - reference solution.
import { useState } from "react";

type Status = "idle" | "saving" | "saved" | "failed";

export function SavePanel({
  save,
  onRender,
}: {
  save: () => Promise<void>;
  onRender: () => void;
}) {
  onRender();

  const [status, setStatus] = useState<Status>("idle");
  const [saves, setSaves] = useState(0);

  const handleSave = async () => {
    // Both of these land in the same tick, so React commits them together.
    setStatus("saving");

    try {
      await save();
      // React 18 and later batch across the await boundary too: one commit.
      setStatus("saved");
      setSaves((current) => current + 1);
    } catch {
      setStatus("failed");
    }
  };

  return (
    <>
      <button type="button" onClick={handleSave}>
        Save
      </button>
      <p role="status">Status: {status}</p>
      <p>Saves: {saves}</p>
    </>
  );
}

// v3ra01_render_triggers / ex5 - reference solution.
import { useState } from "react";

type Message = { id: string; subject: string };

function MessageList({
  messages,
  onRender,
}: {
  messages: Message[];
  onRender: () => void;
}) {
  onRender();
  return (
    <ul>
      {messages.map((message) => (
        <li key={message.id}>{message.subject}</li>
      ))}
    </ul>
  );
}

// The draft is read by nothing but the composer, so it lives in the composer.
// InboxScreen holds no state and therefore never re-renders on a keystroke.
function Composer() {
  const [draft, setDraft] = useState("");

  return (
    <>
      <label htmlFor="draft">Draft</label>
      <input
        id="draft"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
      />
      <p role="status">Draft length: {draft.length}</p>
    </>
  );
}

export function InboxScreen({
  messages,
  onListRender,
}: {
  messages: Message[];
  onListRender: () => void;
}) {
  return (
    <>
      <MessageList messages={messages} onRender={onListRender} />
      <Composer />
    </>
  );
}

