import { useState } from "react";

type Tab = "personal" | "work";

const TITLES: Record<Tab, string> = {
  personal: "Personal",
  work: "Work",
};

function NoteEditor({ title }: { title: string }) {
  const [note, setNote] = useState("");

  return (
    <>
      <h2>{title}</h2>
      <label htmlFor="note">Note</label>
      <input
        id="note"
        value={note}
        onChange={(event) => setNote(event.target.value)}
      />
    </>
  );
}

export function TabbedNotes() {
  const [active, setActive] = useState<Tab>("personal");

  return (
    <>
      <button type="button" onClick={() => setActive("personal")}>
        Personal
      </button>
      <button type="button" onClick={() => setActive("work")}>
        Work
      </button>
      {/* The key makes the two tabs two different identities, so switching
          unmounts one editor and mounts the other with fresh state. */}
      <NoteEditor key={active} title={TITLES[active]} />
    </>
  );
}

// v3ra01_render_triggers / ex7 - reference solution.
import { useState } from "react";

export function PriceForm({
  rate,
  onRender,
}: {
  rate: number;
  onRender: () => void;
}) {
  onRender();

  const [amount, setAmount] = useState("");

  // Derived during render: one commit per keystroke, and the total can never
  // be out of step with the amount because there is nothing to keep in step.
  const parsed = Number(amount);
  const total = Number.isFinite(parsed) ? parsed * rate : 0;

  return (
    <>
      <label htmlFor="amount">Amount</label>
      <input
        id="amount"
        value={amount}
        onChange={(event) => setAmount(event.target.value)}
      />
      <p role="status">Total: {total.toFixed(2)}</p>
    </>
  );
}

