// v3ra01_render_triggers / ex8 - reference solution.
import { useSyncExternalStore } from "react";

type BoardState = { title: string; cards: string[] };

export type BoardStore = {
  subscribe: (listener: () => void) => () => void;
  getSnapshot: () => BoardState;
  addCard: (text: string) => void;
  rename: (title: string) => void;
};

export function createBoardStore(): BoardStore {
  let state: BoardState = { title: "Board", cards: [] };
  const listeners = new Set<() => void>();

  const emit = () => {
    for (const listener of listeners) listener();
  };

  return {
    // Stable identities: React re-subscribes whenever `subscribe` changes.
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    // The same reference comes back until a write replaces it.
    getSnapshot: () => state,
    addCard: (text) => {
      state = { ...state, cards: [...state.cards, text] };
      emit();
    },
    rename: (title) => {
      state = { ...state, title };
      emit();
    },
  };
}

export function useBoardSlice<T>(
  store: BoardStore,
  selector: (state: BoardState) => T,
): T {
  return useSyncExternalStore(store.subscribe, () => selector(store.getSnapshot()));
}

export function CardCount({
  store,
  onRender,
}: {
  store: BoardStore;
  onRender: () => void;
}) {
  onRender();

  // A number, not an array: renaming the board leaves the snapshot equal by
  // Object.is, so React does not schedule a render.
  const count = useBoardSlice(store, (state) => state.cards.length);

  return <p role="status">Cards: {count}</p>;
}

// v3ra01_render_triggers / challenge - reference solution.
import { useState } from "react";
import type { ReactNode } from "react";

type Row = { id: string; label: string };

const MAX_REFRESHES = 3;

function Shell({
  children,
  onRender,
}: {
  children: ReactNode;
  onRender: () => void;
}) {
  onRender();

  const [refreshes, setRefreshes] = useState(0);

  return (
    <>
      <p role="status">Refreshes: {refreshes}</p>
      <button
        type="button"
        // Clamped inside the updater: at the cap the next value equals the
        // current one, so React discards the update and nothing renders.
        onClick={() => setRefreshes((n) => Math.min(n + 1, MAX_REFRESHES))}
      >
        Refresh
      </button>
      {children}
    </>
  );
}

function Chart({ rows, onRender }: { rows: Row[]; onRender: () => void }) {
  onRender();
  return (
    <ul>
      {rows.map((row) => (
        <li key={row.id}>{row.label}</li>
      ))}
    </ul>
  );
}

function FilterPanel({
  rows,
  onRender,
  onChartRender,
}: {
  rows: Row[];
  onRender: () => void;
  onChartRender: () => void;
}) {
  onRender();

  const [query, setQuery] = useState("");
  const needle = query.trim().toLowerCase();
  const matches = needle
    ? rows.filter((row) => row.label.toLowerCase().includes(needle))
    : rows;

  return (
    <>
      <label htmlFor="filter">Filter</label>
      <input
        id="filter"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      <p>Matches: {matches.length}</p>
      <Chart rows={matches} onRender={onChartRender} />
    </>
  );
}

export function AnalyticsBoard({
  rows,
  onShellRender,
  onFilterRender,
  onChartRender,
}: {
  rows: Row[];
  onShellRender: () => void;
  onFilterRender: () => void;
  onChartRender: () => void;
}) {
  // No state here, so this element tree is built once. The filter panel that
  // Shell receives as `children` is therefore the same object on every
  // refresh, and reconciliation stops at it.
  return (
    <Shell onRender={onShellRender}>
      <FilterPanel
        rows={rows}
        onRender={onFilterRender}
        onChartRender={onChartRender}
      />
    </Shell>
  );
}

// v3ra01_render_triggers / review1 - reference solution.
import { useState } from "react";

function Header({ onRender }: { onRender: () => void }) {
  onRender();
  return <h1>Settings</h1>;
}

function Preview({
  compact,
  onRender,
}: {
  compact: boolean;
  onRender: () => void;
}) {
  onRender();
  return <p role="status">Preview: {compact ? "compact" : "comfortable"}</p>;
}

function Form({
  compact,
  onToggleCompact,
  onRender,
}: {
  compact: boolean;
  onToggleCompact: () => void;
  onRender: () => void;
}) {
  onRender();

  // Read by nothing above this component, so it lives here and a keystroke
  // cannot reach the preview.
  const [displayName, setDisplayName] = useState("");

  return (
    <>
      <label htmlFor="compact">Compact mode</label>
      <input
        id="compact"
        type="checkbox"
        checked={compact}
        onChange={onToggleCompact}
      />
      <label htmlFor="display-name">Display name</label>
      <input
        id="display-name"
        value={displayName}
        onChange={(event) => setDisplayName(event.target.value)}
      />
      <p>Name length: {displayName.length}</p>
    </>
  );
}

function SettingsBody({
  onFormRender,
  onPreviewRender,
}: {
  onFormRender: () => void;
  onPreviewRender: () => void;
}) {
  // The lowest common ancestor of the two components that read `compact`.
  const [compact, setCompact] = useState(false);

  return (
    <>
      <Form
        compact={compact}
        onToggleCompact={() => setCompact((current) => !current)}
        onRender={onFormRender}
      />
      <Preview compact={compact} onRender={onPreviewRender} />
    </>
  );
}

export function SettingsPanel({
  onHeaderRender,
  onFormRender,
  onPreviewRender,
}: {
  onHeaderRender: () => void;
  onFormRender: () => void;
  onPreviewRender: () => void;
}) {
  // Stateless, so it never re-renders and the header's element is never
  // rebuilt - the two zeros in the header column.
  return (
    <>
      <Header onRender={onHeaderRender} />
      <SettingsBody
        onFormRender={onFormRender}
        onPreviewRender={onPreviewRender}
      />
    </>
  );
}

