// v3ra02_effect_discipline / ex1 - reference solution.
type Item = { id: string; price: number };

export function OrderSummary({
  items,
  onRender,
}: {
  items: Item[];
  onEffect: () => void;
  onRender: () => void;
}) {
  onRender();

  // Derived during render. There is no second source of truth, so there is
  // nothing to synchronise and no frame in which the two disagree.
  const cents = items.reduce((sum, item) => sum + Math.round(item.price * 100), 0);
  const total = (cents / 100).toFixed(2);

  return (
    <p role="status">
      Items: {items.length} · Total: {total}
    </p>
  );
}

// v3ra02_effect_discipline / ex2 - reference solution.
import { useState } from "react";

export function CommentBox({ postId }: { postId: string }) {
  const [draft, setDraft] = useState("");

  return (
    <>
      <label htmlFor="comment">Comment</label>
      <input
        id="comment"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
      />
      <p>
        Draft for {postId}: {draft.length} characters
      </p>
    </>
  );
}

export function PostPage({ postId }: { postId: string }) {
  return (
    <>
      <h1>Post {postId}</h1>
      {/* A different post is a different comment box. React unmounts the old
          fiber and mounts a new one, so every piece of state below this point
          starts clean - in one commit, with no frame showing stale text. */}
      <CommentBox key={postId} postId={postId} />
    </>
  );
}

// v3ra02_effect_discipline / ex3 - reference solution.
import { useEffect } from "react";

type Connection = { id: string; disconnect: () => void };

export function RoomPresence({
  roomId,
  connect,
}: {
  roomId: string;
  connect: (roomId: string) => Connection;
}) {
  useEffect(() => {
    // `connection` is local to this run, so the cleanup below closes over
    // exactly the connection this run opened - never a later one.
    const connection = connect(roomId);
    return () => connection.disconnect();
  }, [roomId, connect]);

  return <p role="status">In room: {roomId}</p>;
}

// v3ra02_effect_discipline / ex4 - reference solution.
import { useEffect, useState } from "react";

export function PollingStatus({
  options,
  poll,
}: {
  options: { url: string; intervalMs: number };
  poll: (url: string) => Promise<string>;
}) {
  const [status, setStatus] = useState("waiting");

  // The effect reads two primitives, not the object. Destructuring here makes
  // the dependency array honest and stops a re-created literal from restarting
  // the interval on every render of the parent.
  const { url, intervalMs } = options;

  useEffect(() => {
    let ignore = false;

    const id = setInterval(async () => {
      const next = await poll(url);
      if (!ignore) setStatus(next);
    }, intervalMs);

    return () => {
      ignore = true;
      clearInterval(id);
    };
  }, [url, intervalMs, poll]);

  return <p role="status">Status: {status}</p>;
}

exercises.hints:
## Hint 1

Two requests are in flight and the slow one finishes last. Nothing about the
promise knows it has been superseded, so *something in your effect* has to
remember that this particular run is no longer the current one. What does an
effect have that is per-run and that the cleanup can write to?

## Hint 2

A local `let`, flipped by the cleanup:

```tsx
useEffect(() => {
  let ignore = false;
  load(id).then((data) => {
    if (!ignore) setData(data);
  });
  return () => {
    ignore = true;
  };
}, [id]);
```

Each run gets its own `ignore`. The cleanup for the run you abandoned sets *that
run's* flag, which is why this works and a shared ref would not.

## Hint 3

Combine the flag with an `AbortController` created in the same run: pass
`controller.signal` to `fetchWeather`, and in the cleanup set the flag and call
`controller.abort()`. The decision left to you is what the `catch` does — an
aborted request rejects, and reporting that as `unavailable` is the bug this
exercise is really testing for.

