// v3ra02_effect_discipline / ex5 - reference solution.
import { useEffect, useState } from "react";

type Result = { city: string; summary: string };

export function CityWeather({
  city,
  fetchWeather,
}: {
  city: string;
  fetchWeather: (city: string, signal: AbortSignal) => Promise<string>;
}) {
  const [result, setResult] = useState<Result | null>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    // Per-run state: this flag belongs to this effect run and nothing else can
    // reach it, which is precisely why it survives overlapping requests.
    let ignore = false;
    const controller = new AbortController();

    setFailed(false);

    fetchWeather(city, controller.signal)
      .then((summary) => {
        if (!ignore) setResult({ city, summary });
      })
      .catch(() => {
        // An abort is something we caused; it is not a failure to report.
        if (!ignore) setFailed(true);
      });

    return () => {
      ignore = true;
      controller.abort();
    };
  }, [city, fetchWeather]);

  if (failed) return <p role="status">{city}: unavailable</p>;
  if (result === null || result.city !== city) {
    return <p role="status">{city}: loading</p>;
  }
  return (
    <p role="status">
      {result.city}: {result.summary}
    </p>
  );
}

// v3ra02_effect_discipline / ex6 - reference solution.
import { useEffect, useRef, useState } from "react";

export function TickReporter({
  onTick,
  subscribe,
}: {
  onTick: (tick: number) => void;
  subscribe: (handler: (tick: number) => void) => () => void;
}) {
  const [seen, setSeen] = useState(0);

  // A stable box holding the newest callback. Refreshed after every commit -
  // never during render, because a discarded render must not leave a write
  // behind.
  const latest = useRef(onTick);
  useEffect(() => {
    latest.current = onTick;
  });

  useEffect(() => {
    // `subscribe` is what this effect reacts to; `onTick` is only read at the
    // moment a tick happens, so it is not a dependency.
    return subscribe((tick) => {
      setSeen((current) => current + 1);
      latest.current(tick);
    });
  }, [subscribe]);

  return <p role="status">Ticks seen: {seen}</p>;
}

// v3ra02_effect_discipline / ex7 - reference solution.
import { useState } from "react";

export function QuantityPicker({
  label,
  onQuantityChange,
}: {
  label: string;
  onQuantityChange: (quantity: number) => void;
}) {
  const [quantity, setQuantity] = useState(0);

  // One place decides the next value, so the state update and the notification
  // can never disagree - and "only when it actually changed" is a single
  // comparison rather than something reconstructed from render history.
  const change = (next: number) => {
    const clamped = Math.max(next, 0);
    if (clamped === quantity) return;
    setQuantity(clamped);
    onQuantityChange(clamped);
  };

  return (
    <>
      <h2>{label}</h2>
      <p role="status">Quantity: {quantity}</p>
      <button type="button" onClick={() => change(quantity + 1)}>
        Add
      </button>
      <button type="button" onClick={() => change(quantity - 1)}>
        Remove
      </button>
    </>
  );
}

// v3ra02_effect_discipline / ex8 - reference solution.
import { useEffect, useRef, useState } from "react";

const DEBOUNCE_MS = 1000;

export function DraftAutosave({
  draft,
  save,
}: {
  draft: string;
  save: (draft: string) => void;
}) {
  const [saved, setSaved] = useState(0);

  // Per-instance memory that no render reads, so it is a ref, not state:
  // setting state here would cost an extra commit for a flag nobody displays.
  const isFirstRun = useRef(true);

  useEffect(() => {
    if (isFirstRun.current) {
      isFirstRun.current = false;
      return;
    }

    const id = setTimeout(() => {
      save(draft);
      setSaved((current) => current + 1);
    }, DEBOUNCE_MS);

    // Cancels the pending save on the next keystroke and on unmount, which is
    // both the debounce and the leak fix.
    return () => clearTimeout(id);
  }, [draft, save]);

  return <p role="status">Saved: {saved}</p>;
}

