// v3ra02_effect_discipline / challenge - reference solution.
import { useEffect, useState } from "react";

type Result = { id: string; label: string };
type Status = "idle" | "searching" | "done" | "failed";

const DEBOUNCE_MS = 300;

export function LiveSearch({
  search,
}: {
  search: (query: string, signal: AbortSignal) => Promise<Result[]>;
}) {
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState<Status>("idle");
  const [results, setResults] = useState<Result[]>([]);

  useEffect(() => {
    // Rule 6: an empty query is not a search. Returning before anything is
    // created means this run has nothing to clean up.
    if (query.trim() === "") {
      setStatus("idle");
      setResults([]);
      return;
    }

    let ignore = false;
    const controller = new AbortController();

    setStatus("searching");

    const timer = setTimeout(() => {
      search(query, controller.signal)
        .then((rows) => {
          if (ignore) return;
          setResults(rows);
          setStatus("done");
        })
        .catch(() => {
          // Rule 4: we caused the abort, so it is not a failure.
          if (ignore) return;
          setStatus("failed");
        });
    }, DEBOUNCE_MS);

    // Rules 1, 2, 3 and 7: retire everything this run created.
    return () => {
      ignore = true;
      controller.abort();
      clearTimeout(timer);
    };
  }, [query, search]);

  const message =
    status === "idle"
      ? "Type to search"
      : status === "searching"
        ? "Searching…"
        : status === "failed"
          ? "Search failed"
          : `Results: ${results.length}`;

  return (
    <>
      <label htmlFor="search">Search</label>
      <input
        id="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      <p role="status">{message}</p>
      <ul>
        {status === "done" &&
          results.map((result) => <li key={result.id}>{result.label}</li>)}
      </ul>
    </>
  );
}

// v3ra02_effect_discipline / review1 - reference solution.
import { useEffect } from "react";

type Project = { id: string; name: string; members: string[] };

export function ProjectPanel({
  project,
  onProjectOpen,
  track,
}: {
  project: Project;
  onProjectOpen: (projectId: string) => void;
  track: (event: string, projectId: string) => void;
}) {
  // Was an effect writing state from props. It is a derivation: one commit,
  // one source of truth, no way for the two to disagree.
  const memberCount = project.members.length;

  // The only genuine synchronisation in the file: an outside system is told
  // which project is being viewed. Keyed on the id, so a re-created project
  // object with the same id does not re-fire it.
  useEffect(() => {
    track("viewed", project.id);
  }, [track, project.id]);

  return (
    <>
      <h2>{project.name}</h2>
      <p role="status">Members: {memberCount}</p>
      {/* Was an effect. Opening is something the user does, so it belongs in
          the handler - which also stops it firing on mount. */}
      <button type="button" onClick={() => onProjectOpen(project.id)}>
        Open {project.name}
      </button>
    </>
  );
}

lessons.fullReadme:
# V3·RA3 — Refs and measurement (archive)

## Choosing a container

Every value in a component lives in one of four places, and picking wrongly is
the source of most ref confusion:

| Container | Survives renders | Triggers a render | Use for |
| --- | --- | --- | --- |
| A local `const` | no | — | derivations |
| `useState` | yes | yes | anything the UI shows |
| `useRef` | yes | no | per-instance memory the UI does not show |
| Module scope | yes (shared!) | no | true constants |

The two failure modes are symmetrical. A displayed value in a ref means the
screen lags behind reality. A non-displayed value in state means a render per
change for nothing. Both compile, both pass a casual test.

## Worked example — ref as a prop, typed properly

```tsx
import type { Ref } from "react";

export function SearchField({
  label,
  ref,
}: {
  label: string;
  ref?: Ref<HTMLInputElement>;
}) {
  return (
    <>
      <label htmlFor="q">{label}</label>
      <input id="q" ref={ref} />
    </>
  );
}
```

`Ref<T>` — not `RefObject<T>` — because a caller may pass a callback. In React 18
this component needed `forwardRef` and its awkward two-generic signature; in
React 19 `ref` is an ordinary prop and `forwardRef` is on its way out.

## Worked example — a ref callback that owns a subscription

```tsx
const attachObserver = useCallback(
  (node: HTMLDivElement) => {
    const observer = new ResizeObserver(([entry]) => {
      onWidth(entry.contentRect.width);
    });
    observer.observe(node);
    return () => observer.disconnect();
  },
  [onWidth],
);

return <div ref={attachObserver} />;
```

`useCallback` here is load-bearing. Without it the callback is a new function on
every render, React detaches and reattaches the node each time, and you create
and destroy a `ResizeObserver` per render of the parent.

## Worked example — measure and adjust before paint

```tsx
useLayoutEffect(() => {
  const node = spanRef.current;
  if (!node) return;
  setFits(measure(node).width <= MAX_WIDTH);
}, [text, measure]);
```

Two rules keep this out of trouble. First, do the minimum: one read, one write.
Second, make sure the state you set cannot change the thing you measured, or you
have an infinite measure–adjust loop that React will eventually complain about.

## Worked example — a map of nodes

```tsx
const nodes = useRef(new Map<string, HTMLLIElement>());

const register = useCallback(
  (id: string) => (node: HTMLLIElement) => {
    nodes.current.set(id, node);
    return () => {
      nodes.current.delete(id);
    };
  },
  [],
);

<li ref={register(step.id)} key={step.id}>…</li>
```

The teardown's `delete` is the difference between a working component and one
that retains a detached DOM node for every row the user has ever removed.

## Worked example — a handle that is a vocabulary

```tsx
export type TranscriptHandle = {
  focus: () => void;
  scrollToEnd: () => void;
  visibleCount: () => number;
};

useImperativeHandle(
  ref,
  () => ({
    focus: () => listRef.current?.focus(),
    scrollToEnd: () => {
      const node = listRef.current;
      if (node) node.scrollTop = node.scrollHeight;
    },
    visibleCount: () => lines.length,
  }),
  [lines],
);
```

Two things to notice. The internal `listRef` never escapes — what the parent
receives is three verbs, so the markup underneath stays an implementation
detail and can change without breaking a caller. And the dependency array is
real: `visibleCount` closes over `lines`, so `[]` would answer with the first
render's count for the lifetime of the component. Treat the factory exactly as
you would an effect body and list what it reads.

The shortcut people reach for instead —
`useImperativeHandle(ref, () => listRef.current!, [])` — compiles and appears to
work, and publishes your entire DOM subtree as a supported API.

## Common mistakes

- **Reading or writing a ref during render.** Discarded renders leave the write
  behind; Strict Mode double-counts it.
- **Storing displayed data in a ref.** The screen is one interaction behind, and
  only sometimes.
- **Inline ref callbacks that do work.** New identity every render means detach
  and reattach every render.
- **Mixing the two ref-callback protocols.** Either return a cleanup or handle
  `null`; a callback that does both is confusing and one branch will rot.
- **Forgetting `disconnect()`.** An observer holds its callback, which holds the
  component's closure.
- **Exposing the DOM node through an imperative handle.** You have published
  your internals as an API.
- **`useImperativeHandle` with `[]` around a closure over props.** A stale
  handle: it keeps answering with the first render's values.
- **Measuring in `useEffect`.** One painted frame of the wrong layout.
- **Interleaved reads and writes across many nodes.** Layout thrashing; read all,
  then write all.
- **`useLayoutEffect` on the server.** It does not run and React warns; guard it
  or use `useEffect` where the measurement is not visible.

## The two ref-callback protocols

Before React 19, a ref callback was called twice per attachment cycle: once with
the node, once with `null`. Anything created on attach had to be stashed
somewhere that the `null` call could reach, which in practice meant a second
ref, and the two calls drifted apart in every codebase that tried it.

```tsx
// Old: two branches, an external stash, and a leak if they diverge.
ref={(node) => {
  if (node) teardown.current = attach(node);
  else teardown.current?.();
}}

// New: the undo is created in the same closure as the thing it undoes.
ref={(node) => {
  const stop = attach(node);
  return () => stop();
}}
```

Both still work — React falls back to the `null` call for a callback that
returns nothing — but do not mix them within one callback. One consequence of
the change to watch for: a concise arrow body now "returns" whatever the
expression evaluates to, so `ref={(node) => (map.current[id] = node)}` returns
the node. React tolerates it, the lint rules flag it, and a block body is the
correct form.

## Interview answer

> **"When would you reach for a ref, and what are the rules?"**
>
> Two situations. One: I need the actual DOM node to do something the
> declarative API cannot express — focus, scroll, select a range, play a video,
> measure. Two: I need a value that survives renders but that no render reads —
> a timer id, the start position of a drag, a map of child nodes.
>
> The rules are that refs must not be read or written during render, because a
> concurrent render can be discarded and the write would not be, and that
> anything the UI displays must be state, because changing a ref schedules
> nothing.
>
> In React 19 two details changed. `ref` is a normal prop, so `forwardRef` is no
> longer needed to pass one through. And a ref callback can return a cleanup,
> which replaces the old "called again with null" protocol — that makes a
> callback that starts an observer or a subscription pair up correctly, the same
> way an effect and its cleanup do. If a callback does real work, memoize it,
> because otherwise React reattaches the node on every render.

## Check yourself

1. Two jobs for `useRef`. Give a real example of each.
2. Why must a ref not be written during render? Name the two mechanisms that
   make it break.
3. What is the return value of a React 19 ref callback used for?
4. What happens if an inline ref callback starts a `ResizeObserver`?
5. Type the `ref` prop of a component that forwards to an `<input>`. Why not
   `RefObject`?
6. Where exactly does `useLayoutEffect` run within the commit?
7. What visible symptom tells you a measurement is in the wrong effect?
8. Why should an imperative handle not expose the node?
9. What is stale about `useImperativeHandle(ref, () => ({ count: items.length
   }), [])`?
10. Why a `Map` in a ref rather than an array of refs for a dynamic list?
11. What does `setPointerCapture` buy you in a drag handler?
12. Describe layout thrashing and the batching that avoids it.
13. Why does `useLayoutEffect` warn during server rendering?
14. A component shows a value one click behind. What is the most likely cause?

