// v3ra03_refs_and_measurement / ex1 - reference solution.
import { useRef } from "react";

export function ClickAudit({
  onRender,
  onReport,
}: {
  onRender: () => void;
  onReport: (total: number) => void;
}) {
  onRender();

  // Per-instance memory that no render reads. Writing it schedules nothing,
  // which is exactly the property this component needs.
  const tally = useRef(0);

  return (
    <>
      <p role="status">Audit armed</p>
      <button type="button" onClick={() => (tally.current += 1)}>
        Record
      </button>
      <button type="button" onClick={() => onReport(tally.current)}>
        Show total
      </button>
    </>
  );
}

// v3ra03_refs_and_measurement / ex2 - reference solution.
import { useCallback } from "react";

export function HighlightBox({
  visible,
  attach,
  label,
}: {
  visible: boolean;
  attach: (node: HTMLDivElement) => () => void;
  label: string;
}) {
  // Memoized so a changed `label` does not change the callback's identity -
  // React would otherwise detach and reattach the node on every render.
  const attachBox = useCallback(
    (node: HTMLDivElement) => {
      // React 19: whatever we return is called when the node detaches, and it
      // closes over exactly the node this attach received.
      return attach(node);
    },
    [attach],
  );

  if (!visible) return <p>{label}</p>;

  return (
    <div data-testid="box" ref={attachBox}>
      {label}
    </div>
  );
}

// v3ra03_refs_and_measurement / ex3 - reference solution.
import { useId, useRef } from "react";
import type { Ref } from "react";

export function SearchField({
  label,
  ref,
}: {
  label: string;
  // Ref<T>, not RefObject<T>: a caller may legitimately pass a callback.
  ref?: Ref<HTMLInputElement>;
}) {
  const id = useId();

  return (
    <>
      <label htmlFor={id}>{label}</label>
      <input id={id} ref={ref} />
    </>
  );
}

export function SearchPanel() {
  const inputRef = useRef<HTMLInputElement>(null);

  return (
    <>
      <SearchField label="Search" ref={inputRef} />
      <button type="button" onClick={() => inputRef.current?.focus()}>
        Focus search
      </button>
      <p role="status">Ready</p>
    </>
  );
}

// v3ra03_refs_and_measurement / ex4 - reference solution.
import { useLayoutEffect, useRef, useState } from "react";

const MAX_WIDTH = 160;

export function FitLabel({
  text,
  measure,
}: {
  text: string;
  measure: (node: HTMLSpanElement) => { width: number };
}) {
  const spanRef = useRef<HTMLSpanElement>(null);
  const [fits, setFits] = useState(true);

  // After the commit, before the paint: the correction is applied in the same
  // task, so no frame is ever painted with the wrong attribute.
  useLayoutEffect(() => {
    const node = spanRef.current;
    if (node === null) return;
    setFits(measure(node).width <= MAX_WIDTH);
  }, [text, measure]);

  return (
    <span ref={spanRef} data-fits={fits ? "yes" : "no"}>
      {text}
    </span>
  );
}

exercises.hints:
## Hint 1

Three requirements, and each one names a different moment: when the node
appears, when the component merely re-renders, and when the node goes away. A
ref callback with a teardown is the only construct that has all three moments in
one place.

## Hint 2

The shape, with a real browser observer:

```tsx
const attach = useCallback((node: HTMLDivElement) => {
  const observer = new IntersectionObserver(([entry]) => {
    onVisible(entry.isIntersecting);
  });
  observer.observe(node);
  return () => observer.disconnect();
}, [onVisible]);
```

The observer is a `const` in the same closure as the `disconnect` that retires
it, so they cannot get out of step.

## Hint 3

Memoize the ref callback on `[createObserver]` and let it create, observe and
return the disconnect. The decision left to you is where the width lives: it is
on screen, so it must be state — and the setter is safe to call from the
observer callback because React setters are stable and the updater form is
available if you need the previous value.

