// v3ra03_refs_and_measurement / ex5 - reference solution.
import { useCallback, useState } from "react";

type Observer = {
  observe: (node: Element) => void;
  disconnect: () => void;
};

export function SizeReporter({
  createObserver,
  label,
}: {
  createObserver: (onEntry: (width: number) => void) => Observer;
  label: string;
}) {
  const [width, setWidth] = useState(0);

  // Memoized on the factory alone: a changed `label` must not tear the
  // observer down and build a new one.
  const attach = useCallback(
    (node: HTMLDivElement) => {
      const observer = createObserver((next) => setWidth(next));
      observer.observe(node);
      // The teardown retires the observer this attach created - nothing is
      // carried between calls, so the two cannot get out of step.
      return () => observer.disconnect();
    },
    [createObserver],
  );

  return (
    <>
      <div data-testid="panel" ref={attach}>
        {label}
      </div>
      <p role="status">Width: {width}</p>
    </>
  );
}

// v3ra03_refs_and_measurement / ex6 - reference solution.
import { useImperativeHandle, useRef } from "react";
import type { Ref } from "react";

export type TranscriptHandle = {
  focus: () => void;
  scrollToEnd: () => void;
  visibleCount: () => number;
};

export function TranscriptLog({
  lines,
  ref,
}: {
  lines: string[];
  ref?: Ref<TranscriptHandle>;
}) {
  const listRef = useRef<HTMLUListElement>(null);

  // A vocabulary, not a node: the parent gets three verbs and no access to the
  // markup, so the markup stays an implementation detail.
  useImperativeHandle(
    ref,
    () => ({
      focus: () => listRef.current?.focus(),
      scrollToEnd: () => {
        const node = listRef.current;
        if (node) node.scrollTop = node.scrollHeight;
      },
      // Reads `lines`, so `lines` is a dependency - with [] this would answer
      // with the first render's count for ever.
      visibleCount: () => lines.length,
    }),
    [lines],
  );

  return (
    <ul ref={listRef} tabIndex={-1}>
      {lines.map((line, index) => (
        <li key={`${index}-${line}`}>{line}</li>
      ))}
    </ul>
  );
}

export function TranscriptScreen({
  lines,
  onCount,
}: {
  lines: string[];
  onCount: (count: number) => void;
}) {
  const logRef = useRef<TranscriptHandle>(null);

  return (
    <>
      <TranscriptLog lines={lines} ref={logRef} />
      <button type="button" onClick={() => logRef.current?.focus()}>
        Focus log
      </button>
      <button type="button" onClick={() => logRef.current?.scrollToEnd()}>
        Jump to end
      </button>
      <button
        type="button"
        onClick={() => onCount(logRef.current?.visibleCount() ?? 0)}
      >
        Count visible
      </button>
    </>
  );
}

// v3ra03_refs_and_measurement / ex7 - reference solution.
import { useRef } from "react";
import type { PointerEvent as ReactPointerEvent } from "react";

export function DragMeter({
  onDrag,
  onRender,
}: {
  onDrag: (delta: number) => void;
  onRender: () => void;
}) {
  onRender();

  // `null` means "not dragging", so the two facts cannot disagree - and
  // neither is on screen, so neither is state.
  const startX = useRef<number | null>(null);

  const handleDown = (event: ReactPointerEvent<HTMLDivElement>) => {
    startX.current = event.clientX;
    // Without capture, a pointer that leaves the element stops sending moves
    // and never delivers the pointerup that ends the drag.
    event.currentTarget.setPointerCapture(event.pointerId);
  };

  const handleMove = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (startX.current === null) return;
    onDrag(event.clientX - startX.current);
  };

  const handleUp = (event: ReactPointerEvent<HTMLDivElement>) => {
    startX.current = null;
    event.currentTarget.releasePointerCapture(event.pointerId);
  };

  return (
    <div
      role="slider"
      data-testid="track"
      onPointerDown={handleDown}
      onPointerMove={handleMove}
      onPointerUp={handleUp}
    >
      Drag me
    </div>
  );
}

exercises.hints:
## Hint 1

You cannot call `useRef` in a loop — the hook list is positional, and the number
of steps changes. So you need *one* container holding many nodes, and the thing
that changes per row is the key you store under, not the hook.

## Hint 2

One ref holding a `Map`, and a factory that produces a ref callback bound to an
id:

```tsx
const nodes = useRef(new Map<string, HTMLLIElement>());

const register = (id: string) => (node: HTMLLIElement) => {
  nodes.current.set(id, node);
  return () => {
    nodes.current.delete(id);
  };
};
```

The returned teardown is what keeps the map honest when a row disappears.

## Hint 3

Store the map in `useRef(new Map(...))`, register each `<li>` with the factory,
and look the node up by id in the button handler. The decision left to you is
whether `register` should be memoized: an unmemoized factory produces a new
callback per row per render, so React re-registers every row on every render.
Work out whether that is harmless here, and whether you would accept it in a
list of a thousand rows.

