// v3ra03_refs_and_measurement / ex8 - reference solution.
import { useCallback, useRef } from "react";

type Step = { id: string; label: string };

export function StepList({
  steps,
  scrollTo,
  onRegistrySize,
}: {
  steps: Step[];
  scrollTo: (node: HTMLLIElement) => void;
  onRegistrySize: (size: number) => void;
}) {
  // One container for many nodes: hooks cannot be called per row, but a Map in
  // a single ref can hold as many as the list has.
  const nodes = useRef(new Map<string, HTMLLIElement>());

  const register = useCallback(
    (id: string) => (node: HTMLLIElement) => {
      nodes.current.set(id, node);
      // Without this, every removed row leaves a detached DOM node behind.
      return () => {
        nodes.current.delete(id);
      };
    },
    [],
  );

  return (
    <>
      {steps.map((step) => (
        <button
          key={step.id}
          type="button"
          onClick={() => {
            const node = nodes.current.get(step.id);
            if (node) scrollTo(node);
          }}
        >
          Go to {step.label}
        </button>
      ))}
      <button type="button" onClick={() => onRegistrySize(nodes.current.size)}>
        Report registry
      </button>
      <ul>
        {steps.map((step) => (
          <li key={step.id} ref={register(step.id)}>
            {step.label}
          </li>
        ))}
      </ul>
    </>
  );
}

