// v3ra03_refs_and_measurement / challenge - reference solution.
import {
  useCallback,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import type { KeyboardEvent as ReactKeyboardEvent, ReactNode, Ref } from "react";

export type PopoverHandle = { open: () => void; close: () => void };

type Placement = "above" | "below";

export function Popover({
  label,
  content,
  measure,
  ref,
}: {
  label: string;
  content: ReactNode;
  measure: (
    trigger: HTMLButtonElement,
    panel: HTMLDivElement,
  ) => { spaceBelow: number; panelHeight: number };
  ref?: Ref<PopoverHandle>;
}) {
  const [open, setOpen] = useState(false);
  const [placement, setPlacement] = useState<Placement>("below");

  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const wasOpen = useRef(false);

  const close = useCallback(() => setOpen(false), []);
  const openPanel = useCallback(() => setOpen(true), []);

  useImperativeHandle(ref, () => ({ open: openPanel, close }), [openPanel, close]);

  // Runs after the panel is in the DOM and before the browser paints, so the
  // provisional placement rendered above is never actually seen.
  useLayoutEffect(() => {
    if (!open) {
      // Closing: give focus back, but not on the initial mount.
      if (wasOpen.current) triggerRef.current?.focus();
      wasOpen.current = false;
      return;
    }

    const trigger = triggerRef.current;
    const panel = panelRef.current;
    if (trigger === null || panel === null) return;

    const { spaceBelow, panelHeight } = measure(trigger, panel);
    setPlacement(spaceBelow >= panelHeight ? "below" : "above");
    panel.focus();
    wasOpen.current = true;
  }, [open, measure]);

  const handleKeyDown = (event: ReactKeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Escape") close();
  };

  return (
    <>
      <button
        type="button"
        ref={triggerRef}
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        {label}
      </button>
      {open && (
        <div
          role="dialog"
          tabIndex={-1}
          ref={panelRef}
          data-placement={placement}
          onKeyDown={handleKeyDown}
        >
          {content}
          <button type="button" onClick={close}>
            Close
          </button>
        </div>
      )}
    </>
  );
}

