// v3ra04_reducer_modelling / ex1 - reference solution.
import { useReducer } from "react";

export type Item = { id: string; name: string; quantity: number };
export type CartState = { items: Item[] };

export type CartAction =
  | { type: "added"; item: Item }
  | { type: "removed"; id: string }
  | { type: "quantityChanged"; id: string; quantity: number }
  | { type: "cleared" };

function withoutItem(state: CartState, id: string): CartState {
  const items = state.items.filter((item) => item.id !== id);
  // Nothing matched: hand back the same object so React bails out.
  return items.length === state.items.length ? state : { items };
}

export function cartReducer(state: CartState, action: CartAction): CartState {
  switch (action.type) {
    case "added": {
      const existing = state.items.find((item) => item.id === action.item.id);
      if (existing) {
        return {
          items: state.items.map((item) =>
            item.id === action.item.id
              ? { ...item, quantity: item.quantity + action.item.quantity }
              : item,
          ),
        };
      }
      return { items: [...state.items, action.item] };
    }
    case "removed":
      return withoutItem(state, action.id);
    case "quantityChanged": {
      // The rule lives in the reducer, so no caller can forget it.
      if (action.quantity <= 0) return withoutItem(state, action.id);
      return {
        items: state.items.map((item) =>
          item.id === action.id ? { ...item, quantity: action.quantity } : item,
        ),
      };
    }
    case "cleared":
      return state.items.length === 0 ? state : { items: [] };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled cart action: ${JSON.stringify(impossible)}`);
    }
  }
}

export function CartPanel({
  catalogue,
}: {
  catalogue: { id: string; name: string }[];
}) {
  const [state, dispatch] = useReducer(cartReducer, { items: [] });

  const units = state.items.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <>
      {catalogue.map((entry) => (
        <button
          key={entry.id}
          type="button"
          onClick={() =>
            dispatch({
              type: "added",
              item: { id: entry.id, name: entry.name, quantity: 1 },
            })
          }
        >
          Add {entry.name}
        </button>
      ))}
      <p role="status">
        Lines: {state.items.length} · Units: {units}
      </p>
      <button type="button" onClick={() => dispatch({ type: "cleared" })}>
        Clear
      </button>
      <ul>
        {state.items.map((item) => (
          <li key={item.id}>
            {item.name} × {item.quantity}
            <button
              type="button"
              onClick={() => dispatch({ type: "removed", id: item.id })}
            >
              Remove {item.name}
            </button>
          </li>
        ))}
      </ul>
    </>
  );
}

// v3ra04_reducer_modelling / ex2 - reference solution.
import { useReducer } from "react";

export type FilterState = { active: string[]; initial: string[] };

export type FilterAction =
  | { type: "added"; filter: string }
  | { type: "reset" };

export function filterReducer(
  state: FilterState,
  action: FilterAction,
): FilterState {
  switch (action.type) {
    case "added":
      return state.active.includes(action.filter)
        ? state
        : { ...state, active: [...state.active, action.filter] };
    case "reset":
      // Already at the starting point: same object, so React bails out.
      return state.active === state.initial
        ? state
        : { ...state, active: state.initial };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled filter action: ${JSON.stringify(impossible)}`);
    }
  }
}

export function FilterBoard({
  savedFilters,
  parseFilters,
  label,
}: {
  savedFilters: string;
  parseFilters: (raw: string) => { active: string[] };
  label: string;
}) {
  // The third argument runs once, at mount, and is the only place the starting
  // point is computed. Writing useReducer(filterReducer,
  // parseFilters(savedFilters)) would parse on every render and discard every
  // result but the first.
  const [state, dispatch] = useReducer(
    filterReducer,
    savedFilters,
    (raw): FilterState => {
      const parsed = parseFilters(raw);
      // The starting point lives in the state, so Reset never needs to parse
      // again and the reducer stays a plain top-level function.
      return { active: parsed.active, initial: parsed.active };
    },
  );

  return (
    <>
      <h2>{label}</h2>
      <p role="status">Active: {state.active.length}</p>
      <button
        type="button"
        onClick={() => dispatch({ type: "added", filter: "draft" })}
      >
        Add draft
      </button>
      <button type="button" onClick={() => dispatch({ type: "reset" })}>
        Reset
      </button>
    </>
  );
}

// v3ra04_reducer_modelling / ex3 - reference solution.
import { useReducer, useState } from "react";

export type Note = { id: string; text: string; at: number };

export type NoteAction =
  | { type: "noteAdded"; id: string; text: string; at: number }
  | { type: "noteRemoved"; id: string };

// Pure: same state plus same action always gives the same result. Nothing here
// reads the clock, a random source, or anything outside its arguments.
export function noteReducer(state: Note[], action: NoteAction): Note[] {
  switch (action.type) {
    case "noteAdded":
      return [...state, { id: action.id, text: action.text, at: action.at }];
    case "noteRemoved": {
      const next = state.filter((note) => note.id !== action.id);
      return next.length === state.length ? state : next;
    }
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled note action: ${JSON.stringify(impossible)}`);
    }
  }
}

export function NoteBoard({
  newId,
  now,
}: {
  newId: () => string;
  now: () => number;
}) {
  const [notes, dispatch] = useReducer(noteReducer, []);
  const [draft, setDraft] = useState("");

  const add = () => {
    const text = draft.trim();
    if (text === "") return;
    // The handler is where the outside world is allowed in: it stamps the id
    // and the time and hands them to the reducer as data.
    dispatch({ type: "noteAdded", id: newId(), text, at: now() });
    setDraft("");
  };

  return (
    <>
      <label htmlFor="note">Note</label>
      <input
        id="note"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
      />
      <button type="button" onClick={add}>
        Add
      </button>
      <p role="status">Notes: {notes.length}</p>
      <ul>
        {notes.map((note) => (
          <li key={note.id}>
            {note.text} @ {note.at}
          </li>
        ))}
      </ul>
    </>
  );
}

// v3ra04_reducer_modelling / ex4 - reference solution.
import { useReducer } from "react";

export type Row = { id: string; label: string };

export type ReportState = { attempts: number } & (
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; rows: Row[] }
  | { status: "failure"; message: string }
);

export type ReportAction =
  | { type: "loadStarted" }
  | { type: "loadSucceeded"; rows: Row[] }
  | { type: "loadFailed"; message: string };

export function reportReducer(
  state: ReportState,
  action: ReportAction,
): ReportState {
  switch (action.type) {
    case "loadStarted":
      // Guarded: starting a load while one is running is not an error, it is
      // nothing. Returning the same object means React bails out.
      return state.status === "loading"
        ? state
        : { status: "loading", attempts: state.attempts + 1 };
    case "loadSucceeded":
      return { status: "success", attempts: state.attempts, rows: action.rows };
    case "loadFailed":
      return {
        status: "failure",
        attempts: state.attempts,
        message: action.message,
      };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled report action: ${JSON.stringify(impossible)}`);
    }
  }
}

const INITIAL: ReportState = { status: "idle", attempts: 0 };

export function ReportLoader({ load }: { load: () => Promise<Row[]> }) {
  const [state, dispatch] = useReducer(reportReducer, INITIAL);

  const start = async () => {
    if (state.status === "loading") return;
    dispatch({ type: "loadStarted" });
    try {
      dispatch({ type: "loadSucceeded", rows: await load() });
    } catch (error) {
      dispatch({ type: "loadFailed", message: String(error) });
    }
  };

  // One switch on one field, instead of a chain of flag questions whose order
  // encodes precedence nobody wrote down.
  const message =
    state.status === "idle"
      ? "Ready"
      : state.status === "loading"
        ? "Loading…"
        : state.status === "success"
          ? `Rows: ${state.rows.length}`
          : `Failed: ${state.message}`;

  return (
    <>
      <button type="button" onClick={start}>
        Load report
      </button>
      <p role="status">{message}</p>
      <p>Attempts: {state.attempts}</p>
      {state.status === "failure" && (
        <button type="button" onClick={start}>
          Retry
        </button>
      )}
    </>
  );
}

