import { useReducer } from "react";

export type History = { past: string[]; present: string; future: string[] };

export type HistoryAction =
  | { type: "edited"; text: string }
  | { type: "undone" }
  | { type: "redone" }
  | { type: "reset"; text: string };

export function historyReducer(
  state: History,
  action: HistoryAction,
): History {
  switch (action.type) {
    case "edited":
      if (action.text === state.present) return state;
      // A new edit truncates everything ahead of the cursor: the redo timeline
      // no longer exists.
      return {
        past: [...state.past, state.present],
        present: action.text,
        future: [],
      };
    case "undone":
      if (state.past.length === 0) return state;
      return {
        past: state.past.slice(0, -1),
        present: state.past[state.past.length - 1],
        future: [state.present, ...state.future],
      };
    case "redone":
      if (state.future.length === 0) return state;
      return {
        past: [...state.past, state.present],
        present: state.future[0],
        future: state.future.slice(1),
      };
    case "reset":
      return { past: [], present: action.text, future: [] };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled history action: ${JSON.stringify(impossible)}`);
    }
  }
}

export function DocumentEditor({ initialText }: { initialText: string }) {
  const [state, dispatch] = useReducer(
    historyReducer,
    initialText,
    (text): History => ({ past: [], present: text, future: [] }),
  );

  return (
    <>
      <label htmlFor="document">Document</label>
      <textarea
        id="document"
        value={state.present}
        onChange={(event) =>
          dispatch({ type: "edited", text: event.target.value })
        }
      />
      <button
        type="button"
        disabled={state.past.length === 0}
        onClick={() => dispatch({ type: "undone" })}
      >
        Undo
      </button>
      <button
        type="button"
        disabled={state.future.length === 0}
        onClick={() => dispatch({ type: "redone" })}
      >
        Redo
      </button>
      <button
        type="button"
        onClick={() => dispatch({ type: "reset", text: initialText })}
      >
        Reset
      </button>
      <p role="status">
        History: {state.past.length} back, {state.future.length} forward
      </p>
    </>
  );
}

// v3ra04_reducer_modelling / ex6 - reference solution.
import { useReducer } from "react";

export type Values = { email: string; password: string; confirm: string };
type Field = keyof Values;

export type SignupState = {
  values: Values;
  touched: Record<Field, boolean>;
};

export type SignupAction =
  | { type: "fieldChanged"; field: Field; value: string }
  | { type: "fieldBlurred"; field: Field }
  | { type: "submitted" };

const INITIAL: SignupState = {
  values: { email: "", password: "", confirm: "" },
  touched: { email: false, password: false, confirm: false },
};

export function signupReducer(
  state: SignupState,
  action: SignupAction,
): SignupState {
  switch (action.type) {
    case "fieldChanged":
      if (state.values[action.field] === action.value) return state;
      return {
        ...state,
        values: { ...state.values, [action.field]: action.value },
      };
    case "fieldBlurred":
      if (state.touched[action.field]) return state;
      return {
        ...state,
        touched: { ...state.touched, [action.field]: true },
      };
    case "submitted":
      // The reducer knows nothing about the validation rules; it only records
      // that the user has now been shown everything.
      return {
        ...state,
        touched: { email: true, password: true, confirm: true },
      };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled signup action: ${JSON.stringify(impossible)}`);
    }
  }
}

function validate(values: Values): Record<Field, string | null> {
  return {
    email: values.email.includes("@") ? null : "Email needs an @",
    password:
      values.password.length >= 8 ? null : "Password needs 8 characters",
    confirm: values.confirm === values.password ? null : "Passwords must match",
  };
}

export function SignupForm({ onSubmit }: { onSubmit: (values: Values) => void }) {
  const [state, dispatch] = useReducer(signupReducer, INITIAL);

  // Derived every render, so a fixed field cannot keep showing its old message.
  const errors = validate(state.values);
  const isValid = Object.values(errors).every((error) => error === null);

  const fields: { field: Field; label: string; type: string }[] = [
    { field: "email", label: "Email", type: "text" },
    { field: "password", label: "Password", type: "password" },
    { field: "confirm", label: "Confirm password", type: "password" },
  ];

  return (
    <>
      {fields.map(({ field, label, type }) => (
        <div key={field}>
          <label htmlFor={field}>{label}</label>
          <input
            id={field}
            type={type}
            value={state.values[field]}
            onChange={(event) =>
              dispatch({ type: "fieldChanged", field, value: event.target.value })
            }
            onBlur={() => dispatch({ type: "fieldBlurred", field })}
          />
          {state.touched[field] && errors[field] !== null && (
            <p role="alert">{errors[field]}</p>
          )}
        </div>
      ))}
      <button
        type="button"
        onClick={() => {
          dispatch({ type: "submitted" });
          if (isValid) onSubmit(state.values);
        }}
      >
        Create account
      </button>
    </>
  );
}

