import { memo, useReducer } from "react";
import type { Dispatch } from "react";

export type CounterAction =
  | { type: "incremented" }
  | { type: "decremented" }
  | { type: "reset" };

export function counterReducer(state: number, action: CounterAction): number {
  switch (action.type) {
    case "incremented":
      return state + 1;
    case "decremented":
      return state - 1;
    case "reset":
      return state === 0 ? state : 0;
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled counter action: ${JSON.stringify(impossible)}`);
    }
  }
}

export const Controls = memo(function Controls({
  dispatch,
  onRender,
}: {
  dispatch: Dispatch<CounterAction>;
  onRender: () => void;
}) {
  onRender();

  return (
    <>
      <button type="button" onClick={() => dispatch({ type: "incremented" })}>
        Increment
      </button>
      <button type="button" onClick={() => dispatch({ type: "decremented" })}>
        Decrement
      </button>
      <button type="button" onClick={() => dispatch({ type: "reset" })}>
        Reset
      </button>
    </>
  );
});

export function CounterBoard({
  onControlsRender,
}: {
  onControlsRender: () => void;
}) {
  const [count, dispatch] = useReducer(counterReducer, 0);

  return (
    <>
      <p role="status">Count: {count}</p>
      <p>Doubled: {count * 2}</p>
      {/* Both props keep their identity for the life of the component -
          `dispatch` is guaranteed stable and `onControlsRender` comes from
          above - so memo's comparison passes on every render. No useCallback. */}
      <Controls dispatch={dispatch} onRender={onControlsRender} />
    </>
  );
}

exercises.hints:
## Hint 1

`map` always allocates a new array, even when the callback returns every element
unchanged. So the identity requirements are not about `map` — they are about
what you do *after* it: compare, and decide whether to keep the old value.

## Hint 2

Delegate, then check whether anything actually moved:

```tsx
let changed = false;
const cards = state.cards.map((card) => {
  if (card.id !== action.cardId) return card;
  const next = cardReducer(card, action);
  if (next !== card) changed = true;
  return next;
});
return changed ? { ...state, cards } : state;
```

`cardReducer` returning the same card for a no-op is what makes this work, so it
needs the same discipline internally.

## Hint 3

Give `cardReducer` its own exhaustive switch and its own no-op returns — `toggled`
always changes, but `renamed` to the same title does not. The decision left to
you is how `boardReducer` recognises a delegated action: a `cardId` field on the
variant is the simplest, and a nested `{ type: "card"; cardId; action }` shape is
the one that scales. Pick one and say what the other costs.

