// v3ra04_reducer_modelling / ex8 - reference solution.
import { useReducer } from "react";

export type Card = { id: string; title: string; done: boolean; votes: number };
export type BoardState = { name: string; cards: Card[] };

export type CardAction =
  | { type: "toggled"; cardId: string }
  | { type: "renamed"; cardId: string; title: string }
  | { type: "upvoted"; cardId: string };

export type BoardAction =
  | CardAction
  | { type: "boardRenamed"; name: string }
  | { type: "cardAdded"; card: Card };

// Knows nothing about boards, so it can be unit-tested with one object.
export function cardReducer(card: Card, action: CardAction): Card {
  switch (action.type) {
    case "toggled":
      return { ...card, done: !card.done };
    case "renamed":
      return card.title === action.title ? card : { ...card, title: action.title };
    case "upvoted":
      return { ...card, votes: card.votes + 1 };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled card action: ${JSON.stringify(impossible)}`);
    }
  }
}

function isCardAction(action: BoardAction): action is CardAction {
  return "cardId" in action;
}

export function boardReducer(
  state: BoardState,
  action: BoardAction,
): BoardState {
  if (isCardAction(action)) {
    let changed = false;
    const cards = state.cards.map((card) => {
      if (card.id !== action.cardId) return card;
      const next = cardReducer(card, action);
      if (next !== card) changed = true;
      return next;
    });
    // map always allocates; only keep the new array if something moved. Every
    // untouched card keeps its identity, so memoized rows stay still.
    return changed ? { ...state, cards } : state;
  }

  switch (action.type) {
    case "boardRenamed":
      return state.name === action.name ? state : { ...state, name: action.name };
    case "cardAdded":
      return { ...state, cards: [...state.cards, action.card] };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled board action: ${JSON.stringify(impossible)}`);
    }
  }
}

export function Board({
  initialState,
  onCardsIdentity,
}: {
  initialState: BoardState;
  onCardsIdentity: (cards: Card[]) => void;
}) {
  const [state, dispatch] = useReducer(boardReducer, initialState);

  onCardsIdentity(state.cards);

  return (
    <>
      <h2>{state.name}</h2>
      <ul>
        {state.cards.map((card) => (
          <li key={card.id}>
            {card.title} — {card.done ? "done" : "to do"} — {card.votes}
            <button
              type="button"
              onClick={() => dispatch({ type: "toggled", cardId: card.id })}
            >
              Toggle {card.title}
            </button>
            <button
              type="button"
              onClick={() => dispatch({ type: "upvoted", cardId: card.id })}
            >
              Upvote {card.title}
            </button>
          </li>
        ))}
      </ul>
    </>
  );
}

// v3ra04_reducer_modelling / challenge - reference solution.
import { useReducer } from "react";

export type Line = {
  id: string;
  name: string;
  unitPence: number;
  quantity: number;
};

export type CheckoutState =
  | { status: "shopping"; lines: Line[] }
  | { status: "reviewing"; lines: Line[] }
  | { status: "paying"; lines: Line[] }
  | { status: "paid"; lines: Line[]; reference: string }
  | { status: "failed"; lines: Line[]; message: string };

export type CheckoutAction =
  | { type: "lineAdded"; line: Line }
  | { type: "lineRemoved"; id: string }
  | { type: "reviewRequested" }
  | { type: "backToShopping" }
  | { type: "paymentStarted" }
  | { type: "paymentSucceeded"; reference: string }
  | { type: "paymentFailed"; message: string };

function withLines(state: CheckoutState, action: CheckoutAction): CheckoutState {
  if (action.type === "lineAdded") {
    const existing = state.lines.find((line) => line.id === action.line.id);
    const lines = existing
      ? state.lines.map((line) =>
          line.id === action.line.id
            ? { ...line, quantity: line.quantity + action.line.quantity }
            : line,
        )
      : [...state.lines, action.line];
    return { ...state, lines };
  }

  const lines = state.lines.filter((line) => line.id !== action.id);
  // Nothing matched: same object, so React bails out.
  return lines.length === state.lines.length ? state : { ...state, lines };
}

// Switching on the state first makes the guards structural: anything an
// arm does not name falls through to `return state`, which React treats as
// "nothing happened".
export function checkoutReducer(
  state: CheckoutState,
  action: CheckoutAction,
): CheckoutState {
  switch (state.status) {
    case "shopping":
      if (action.type === "lineAdded" || action.type === "lineRemoved") {
        return withLines(state, action);
      }
      if (action.type === "reviewRequested" && state.lines.length > 0) {
        return { status: "reviewing", lines: state.lines };
      }
      return state;

    case "reviewing":
      if (action.type === "lineRemoved") return withLines(state, action);
      if (action.type === "backToShopping") {
        return { status: "shopping", lines: state.lines };
      }
      if (action.type === "paymentStarted") {
        return { status: "paying", lines: state.lines };
      }
      return state;

    case "paying":
      if (action.type === "paymentSucceeded") {
        return {
          status: "paid",
          lines: state.lines,
          reference: action.reference,
        };
      }
      if (action.type === "paymentFailed") {
        return { status: "failed", lines: state.lines, message: action.message };
      }
      return state;

    case "failed":
      if (action.type === "backToShopping") {
        return { status: "shopping", lines: state.lines };
      }
      if (action.type === "paymentStarted") {
        return { status: "paying", lines: state.lines };
      }
      return state;

    case "paid":
      return state;

    default: {
      const impossible: never = state;
      throw new Error(`Unhandled state: ${JSON.stringify(impossible)}`);
    }
  }
}

const INITIAL: CheckoutState = { status: "shopping", lines: [] };

export function Checkout({
  catalogue,
  pay,
  onTransition,
}: {
  catalogue: { id: string; name: string; unitPence: number }[];
  pay: () => Promise<string>;
  onTransition: (from: string, action: string, to: string) => void;
}) {
  const [state, dispatch] = useReducer(checkoutReducer, INITIAL);

  // The reducer stays pure; the reporting happens here, where both the old and
  // the new state are visible and a rejected action is distinguishable.
  const send = (action: CheckoutAction) => {
    const next = checkoutReducer(state, action);
    if (next === state) return;
    onTransition(state.status, action.type, next.status);
    dispatch(action);
  };

  // Derived, in pence: no transition can forget to update a total that does
  // not exist, and integer arithmetic cannot drift.
  const totalPence = state.lines.reduce(
    (sum, line) => sum + line.unitPence * line.quantity,
    0,
  );

  const startPayment = async () => {
    send({ type: "paymentStarted" });
    try {
      send({ type: "paymentSucceeded", reference: await pay() });
    } catch (error) {
      send({ type: "paymentFailed", message: String(error) });
    }
  };

  return (
    <>
      <p role="status">{state.status}</p>
      {catalogue.map((entry) => (
        <button
          key={entry.id}
          type="button"
          onClick={() =>
            send({ type: "lineAdded", line: { ...entry, quantity: 1 } })
          }
        >
          Add {entry.name}
        </button>
      ))}
      <ul>
        {state.lines.map((line) => (
          <li key={line.id}>
            {line.name} × {line.quantity}
          </li>
        ))}
      </ul>
      <p>Total: £{(totalPence / 100).toFixed(2)}</p>
      {state.status === "shopping" && (
        <button
          type="button"
          disabled={state.lines.length === 0}
          onClick={() => send({ type: "reviewRequested" })}
        >
          Review
        </button>
      )}
      {(state.status === "reviewing" || state.status === "failed") && (
        <button
          type="button"
          onClick={() => send({ type: "backToShopping" })}
        >
          Back
        </button>
      )}
      {state.status === "reviewing" && (
        <button type="button" onClick={startPayment}>
          Pay
        </button>
      )}
      {state.status === "failed" && (
        <button type="button" onClick={startPayment}>
          Try again
        </button>
      )}
      {state.status === "paid" && <p>Reference: {state.reference}</p>}
    </>
  );
}

// v3ra04_reducer_modelling / review1 - reference solution.
import { useReducer } from "react";

export type Track = { id: string; title: string; seconds: number };
export type PlaylistState = { tracks: Track[]; shuffle: boolean };

export type PlaylistAction =
  | { type: "trackAdded"; track: Track }
  | { type: "shuffleToggled" }
  | { type: "cleared" };

export function totalSeconds(tracks: Track[]): number {
  return tracks.reduce((sum, track) => sum + track.seconds, 0);
}

export function playlistReducer(
  state: PlaylistState,
  action: PlaylistAction,
): PlaylistState {
  switch (action.type) {
    case "trackAdded":
      // Fault 1: the old version pushed into the array React already held and
      // returned the same reference, so nothing was ever scheduled.
      return { ...state, tracks: [...state.tracks, action.track] };
    case "shuffleToggled":
      return { ...state, shuffle: !state.shuffle };
    case "cleared":
      // Fault 3: a no-op must return the same object, or React commits for a
      // button press that did nothing.
      return state.tracks.length === 0 ? state : { ...state, tracks: [] };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled playlist action: ${JSON.stringify(impossible)}`);
    }
  }
}

const INITIAL: PlaylistState = { tracks: [], shuffle: false };

export function PlaylistPanel({
  tracks,
  onPanelRender,
}: {
  tracks: Track[];
  onPanelRender: () => void;
}) {
  onPanelRender();

  const [state, dispatch] = useReducer(playlistReducer, INITIAL);

  // Fault 2: the total was a command-shaped action carrying a number the
  // caller computed. It is a function of the tracks, so it is derived and no
  // transition can forget to keep it in step.
  const total = totalSeconds(state.tracks);

  return (
    <>
      <div role="status">
        <p>Tracks: {state.tracks.length}</p>
        <p>Total: {total}s</p>
        <p>Shuffle: {state.shuffle ? "on" : "off"}</p>
      </div>
      {tracks.map((track) => (
        <button
          key={track.id}
          type="button"
          onClick={() => dispatch({ type: "trackAdded", track })}
        >
          Add {track.title}
        </button>
      ))}
      <button type="button" onClick={() => dispatch({ type: "shuffleToggled" })}>
        Shuffle
      </button>
      <button type="button" onClick={() => dispatch({ type: "cleared" })}>
        Clear
      </button>
    </>
  );
}

// v3ra05_context_composition / ex1 - reference solution.
import { createContext, useContext, useMemo } from "react";
import type { ReactNode } from "react";

export type Locale = { locale: string; currency: string };

// Not exported: the hook is the API, the context is the implementation.
const LocaleContext = createContext<Locale | null>(null);

export function useLocale(): Locale {
  const value = useContext(LocaleContext);
  if (value === null) {
    throw new Error("useLocale must be used inside a LocaleProvider");
  }
  // Narrowed, so no consumer ever writes `?.` or `!`.
  return value;
}

export function LocaleProvider({
  locale,
  currency,
  children,
}: {
  locale: string;
  currency: string;
  children: ReactNode;
}) {
  const value = useMemo(() => ({ locale, currency }), [locale, currency]);

  // React 19: the context object is the provider element.
  return <LocaleContext value={value}>{children}</LocaleContext>;
}

export function CurrencyLabel() {
  const { locale, currency } = useLocale();
  return (
    <p role="status">
      Currency: {currency} ({locale})
    </p>
  );
}

// v3ra05_context_composition / ex2 - reference solution.
import { createContext, useCallback, useContext, useMemo, useState } from "react";
import type { ReactNode } from "react";

type Session = {
  user: string | null;
  signIn: (name: string) => void;
  signOut: () => void;
};

const SessionContext = createContext<Session | null>(null);

export function useSession(): Session {
  const value = useContext(SessionContext);
  if (value === null) {
    throw new Error("useSession must be used inside a SessionProvider");
  }
  return value;
}

export function SessionProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<string | null>(null);

  // Stable leaves: a useMemo over inline arrows would change every render and
  // be exactly as useless as no useMemo at all.
  const signIn = useCallback((name: string) => setUser(name), []);
  const signOut = useCallback(() => setUser(null), []);

  const value = useMemo(
    () => ({ user, signIn, signOut }),
    [user, signIn, signOut],
  );

  return <SessionContext value={value}>{children}</SessionContext>;
}

export function UserBadge({ onRender }: { onRender: () => void }) {
  onRender();

  const { user } = useSession();
  return <p role="status">{user === null ? "Signed out" : `Signed in as ${user}`}</p>;
}

export function AccountScreen({
  onRender,
  onBadgeRender,
}: {
  onRender: () => void;
  onBadgeRender: () => void;
}) {
  onRender();

  const [pings, setPings] = useState(0);

  return (
    <>
      <button type="button" onClick={() => setPings((n) => n + 1)}>
        Ping
      </button>
      <p>Pings: {pings}</p>
      <SessionProvider>
        <SignInControls />
        <UserBadge onRender={onBadgeRender} />
      </SessionProvider>
    </>
  );
}

function SignInControls() {
  const { signIn, signOut } = useSession();
  return (
    <>
      <button type="button" onClick={() => signIn("ada")}>
        Sign in
      </button>
      <button type="button" onClick={signOut}>
        Sign out
      </button>
    </>
  );
}

