import { createContext, useContext, useReducer } from "react";
import type { Dispatch, ReactNode } from "react";

export type Todo = { id: string; text: string; done: boolean };

export type TodoAction =
  | { type: "added"; todo: Todo }
  | { type: "toggled"; id: string }
  | { type: "clearedCompleted" };

export function todosReducer(state: Todo[], action: TodoAction): Todo[] {
  switch (action.type) {
    case "added":
      return [...state, action.todo];
    case "toggled":
      return state.map((todo) =>
        todo.id === action.id ? { ...todo, done: !todo.done } : todo,
      );
    case "clearedCompleted": {
      const next = state.filter((todo) => !todo.done);
      return next.length === state.length ? state : next;
    }
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled todo action: ${JSON.stringify(impossible)}`);
    }
  }
}

const TodosContext = createContext<Todo[] | null>(null);
const TodosDispatchContext = createContext<Dispatch<TodoAction> | null>(null);

export function useTodos(): Todo[] {
  const todos = useContext(TodosContext);
  if (todos === null) throw new Error("useTodos must be used inside a TodosProvider");
  return todos;
}

export function useTodosDispatch(): Dispatch<TodoAction> {
  const dispatch = useContext(TodosDispatchContext);
  if (dispatch === null) {
    throw new Error("useTodosDispatch must be used inside a TodosProvider");
  }
  return dispatch;
}

export function TodosProvider({ children }: { children: ReactNode }) {
  const [todos, dispatch] = useReducer(todosReducer, []);

  // Two values with different change rates. `dispatch` never changes, so the
  // inner provider never notifies anybody - no memo, no useCallback needed.
  return (
    <TodosContext value={todos}>
      <TodosDispatchContext value={dispatch}>{children}</TodosDispatchContext>
    </TodosContext>
  );
}

export function TodoList({ onRender }: { onRender: () => void }) {
  onRender();

  const todos = useTodos();
  const dispatch = useTodosDispatch();

  return (
    <ul>
      {todos.map((todo) => (
        <li key={todo.id}>
          {todo.text} — {todo.done ? "done" : "to do"}
          <button
            type="button"
            onClick={() => dispatch({ type: "toggled", id: todo.id })}
          >
            Toggle {todo.text}
          </button>
        </li>
      ))}
    </ul>
  );
}

export function TodoToolbar({ onRender }: { onRender: () => void }) {
  onRender();

  // Reads only the stable context, so nothing can ever wake this component.
  const dispatch = useTodosDispatch();

  return (
    <>
      <button
        type="button"
        onClick={() =>
          dispatch({
            type: "added",
            todo: { id: String(Date.now()), text: "New task", done: false },
          })
        }
      >
        Add task
      </button>
      <button type="button" onClick={() => dispatch({ type: "clearedCompleted" })}>
        Clear completed
      </button>
    </>
  );
}

// v3ra05_context_composition / ex4 - reference solution.
import { createContext, useCallback, useContext, useMemo, useState } from "react";
import type { ReactNode } from "react";

type Wrapper = ({ children }: { children: ReactNode }) => ReactNode;

export function composeProviders(providers: Wrapper[]): Wrapper {
  return function Composed({ children }: { children: ReactNode }) {
    // reduceRight so index 0 ends up outermost, matching how the array reads.
    return providers.reduceRight<ReactNode>(
      (inner, Provider) => <Provider>{inner}</Provider>,
      children,
    );
  };
}

type Theme = { theme: "day" | "night"; toggleTheme: () => void };
const ThemeContext = createContext<Theme | null>(null);

export function useTheme(): Theme {
  const value = useContext(ThemeContext);
  if (value === null) throw new Error("useTheme must be used inside a ThemeProvider");
  return value;
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<"day" | "night">("day");
  const toggleTheme = useCallback(
    () => setTheme((current) => (current === "day" ? "night" : "day")),
    [],
  );
  const value = useMemo(() => ({ theme, toggleTheme }), [theme, toggleTheme]);
  return <ThemeContext value={value}>{children}</ThemeContext>;
}

type Icons = { iconSet: "outline" | "solid" };
const IconsContext = createContext<Icons | null>(null);

export function useIcons(): Icons {
  const value = useContext(IconsContext);
  if (value === null) throw new Error("useIcons must be used inside an IconsProvider");
  return value;
}

// ORDERING: reads the theme, so it must be mounted inside ThemeProvider.
export function IconsProvider({ children }: { children: ReactNode }) {
  const { theme } = useTheme();
  const value = useMemo<Icons>(
    () => ({ iconSet: theme === "night" ? "solid" : "outline" }),
    [theme],
  );
  return <IconsContext value={value}>{children}</IconsContext>;
}

type Toasts = { toasts: string[]; push: (text: string) => void };
const ToastContext = createContext<Toasts | null>(null);

export function useToasts(): Toasts {
  const value = useContext(ToastContext);
  if (value === null) throw new Error("useToasts must be used inside a ToastProvider");
  return value;
}

export function ToastProvider({ children }: { children: ReactNode }) {
  const [toasts, setToasts] = useState<string[]>([]);
  const push = useCallback(
    (text: string) => setToasts((current) => [...current, text]),
    [],
  );
  const value = useMemo(() => ({ toasts, push }), [toasts, push]);
  return <ToastContext value={value}>{children}</ToastContext>;
}

function Dashboard() {
  const { theme, toggleTheme } = useTheme();
  const { iconSet } = useIcons();
  const { toasts } = useToasts();

  return (
    <>
      <button type="button" onClick={toggleTheme}>
        Toggle theme
      </button>
      <p role="status">
        Theme: {theme} · Icons: {iconSet} · Toasts: {toasts.length}
      </p>
    </>
  );
}

export function App({ providers }: { providers?: Wrapper[] }) {
  const Providers = useMemo(
    () =>
      composeProviders(providers ?? [ThemeProvider, IconsProvider, ToastProvider]),
    [providers],
  );

  return (
    <Providers>
      <Dashboard />
    </Providers>
  );
}

