// v3ra05_context_composition / ex6 - reference solution.
import { createContext, useContext, useSyncExternalStore } from "react";
import type { ReactNode } from "react";

export type BoardState = { title: string; cards: string[] };

export type BoardStore = {
  subscribe: (listener: () => void) => () => void;
  getSnapshot: () => BoardState;
  addCard: (text: string) => void;
  rename: (title: string) => void;
};

export function createBoardStore(initial: BoardState): BoardStore {
  let state = initial;
  const listeners = new Set<() => void>();
  const emit = () => {
    for (const listener of listeners) listener();
  };

  return {
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    // Same reference until a write replaces it: the contract useSyncExternalStore
    // depends on.
    getSnapshot: () => state,
    addCard: (text) => {
      state = { ...state, cards: [...state.cards, text] };
      emit();
    },
    rename: (title) => {
      if (title === state.title) return;
      state = { ...state, title };
      emit();
    },
  };
}

const BoardStoreContext = createContext<BoardStore | null>(null);

function useBoardStore(): BoardStore {
  const store = useContext(BoardStoreContext);
  if (store === null) {
    throw new Error("useBoardSlice must be used inside a BoardStoreProvider");
  }
  return store;
}

export function BoardStoreProvider({
  store,
  children,
}: {
  store: BoardStore;
  children: ReactNode;
}) {
  // The value is the store object, whose identity never changes - so context
  // propagation never fires and nobody is woken by the provider itself.
  return <BoardStoreContext value={store}>{children}</BoardStoreContext>;
}

export function useBoardSlice<T>(select: (state: BoardState) => T): T {
  const store = useBoardStore();
  return useSyncExternalStore(store.subscribe, () => select(store.getSnapshot()));
}

export function CardCount({ onRender }: { onRender: () => void }) {
  onRender();
  // A number: renaming leaves it Object.is-equal, so this never re-renders.
  const count = useBoardSlice((state) => state.cards.length);
  return <p role="status">Cards: {count}</p>;
}

export function BoardTitle({ onRender }: { onRender: () => void }) {
  onRender();
  const title = useBoardSlice((state) => state.title);
  return <h2>{title}</h2>;
}

export function BoardScreen({
  store,
  onCountRender,
  onTitleRender,
}: {
  store: BoardStore;
  onCountRender: () => void;
  onTitleRender: () => void;
}) {
  return (
    <BoardStoreProvider store={store}>
      <BoardTitle onRender={onTitleRender} />
      <CardCount onRender={onCountRender} />
    </BoardStoreProvider>
  );
}

