import { createContext, use, useMemo } from "react";
import type { ReactNode } from "react";

type Features = { analyticsEnabled: boolean };
type Analytics = { visits: number; source: string };

const FeatureContext = createContext<Features>({ analyticsEnabled: false });
const AnalyticsContext = createContext<Analytics | null>(null);

export function FeatureProvider({
  analyticsEnabled,
  children,
}: {
  analyticsEnabled: boolean;
  children: ReactNode;
}) {
  const value = useMemo(() => ({ analyticsEnabled }), [analyticsEnabled]);
  return <FeatureContext value={value}>{children}</FeatureContext>;
}

export function AnalyticsProvider({
  visits,
  source,
  children,
}: {
  visits: number;
  source: string;
  children: ReactNode;
}) {
  const value = useMemo(() => ({ visits, source }), [visits, source]);
  return <AnalyticsContext value={value}>{children}</AnalyticsContext>;
}

export function ReportCard({ title }: { title: string }) {
  const { analyticsEnabled } = use(FeatureContext);

  if (!analyticsEnabled) {
    return <p role="status">Analytics off</p>;
  }

  // After an early return. `useContext` here would be a rules-of-hooks
  // violation; `use` is exempt because a context read does not depend on a
  // stable position in the hook list.
  const analytics = use(AnalyticsContext);
  if (analytics === null) {
    throw new Error("ReportCard needs an AnalyticsProvider when analytics are on");
  }

  return (
    <p role="status">
      {title}: {analytics.visits} visits from {analytics.source}
    </p>
  );
}

