// v3ra05_context_composition / challenge - reference solution.
import {
  createContext,
  useCallback,
  useContext,
  useMemo,
  useReducer,
  useState,
} from "react";
import type { Dispatch, ReactNode } from "react";

type Wrapper = ({ children }: { children: ReactNode }) => ReactNode;

export function composeProviders(providers: Wrapper[]): Wrapper {
  return function Composed({ children }: { children: ReactNode }) {
    return providers.reduceRight<ReactNode>(
      (inner, Provider) => <Provider>{inner}</Provider>,
      children,
    );
  };
}

type Theme = "day" | "night";
const ThemeStateContext = createContext<Theme | null>(null);
const ThemeActionsContext = createContext<{ toggle: () => void } | null>(null);

export function useTheme(): Theme {
  const value = useContext(ThemeStateContext);
  if (value === null) throw new Error("useTheme must be used inside a ThemeProvider");
  return value;
}

export function useThemeActions(): { toggle: () => void } {
  const value = useContext(ThemeActionsContext);
  if (value === null) {
    throw new Error("useThemeActions must be used inside a ThemeProvider");
  }
  return value;
}

export function ThemeProvider({ children }: { children: ReactNode }) {
  const [theme, setTheme] = useState<Theme>("day");
  const toggle = useCallback(
    () => setTheme((current) => (current === "day" ? "night" : "day")),
    [],
  );
  // Never changes, so its consumers are never notified.
  const actions = useMemo(() => ({ toggle }), [toggle]);

  return (
    <ThemeActionsContext value={actions}>
      <ThemeStateContext value={theme}>{children}</ThemeStateContext>
    </ThemeActionsContext>
  );
}

type SessionState = { user: string | null; unread: number };
type SessionAction =
  | { type: "signedIn"; user: string }
  | { type: "signedOut" }
  | { type: "messageArrived" };

function sessionReducer(state: SessionState, action: SessionAction): SessionState {
  switch (action.type) {
    case "signedIn":
      return state.user === action.user ? state : { ...state, user: action.user };
    case "signedOut":
      return state.user === null ? state : { ...state, user: null };
    case "messageArrived":
      return { ...state, unread: state.unread + 1 };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled session action: ${JSON.stringify(impossible)}`);
    }
  }
}

const SessionStateContext = createContext<SessionState | null>(null);
const SessionDispatchContext = createContext<Dispatch<SessionAction> | null>(null);

export function useSession(): SessionState {
  const value = useContext(SessionStateContext);
  if (value === null) {
    throw new Error("useSession must be used inside a SessionProvider");
  }
  return value;
}

export function useSessionActions(): Dispatch<SessionAction> {
  const value = useContext(SessionDispatchContext);
  if (value === null) {
    throw new Error("useSessionActions must be used inside a SessionProvider");
  }
  return value;
}

export function SessionProvider({ children }: { children: ReactNode }) {
  const [session, dispatch] = useReducer(sessionReducer, {
    user: null,
    unread: 0,
  });

  // `dispatch` is stable for the life of the component: no memo required and
  // nothing below this provider is ever woken by it.
  return (
    <SessionDispatchContext value={dispatch}>
      <SessionStateContext value={session}>{children}</SessionStateContext>
    </SessionDispatchContext>
  );
}

function Header({ onRender }: { onRender: () => void }) {
  onRender();
  return <p role="status">Theme: {useTheme()}</p>;
}

function Sidebar({ onRender }: { onRender: () => void }) {
  onRender();
  // Only the two never-changing contexts, so no context can wake this.
  const { toggle } = useThemeActions();
  const dispatch = useSessionActions();

  return (
    <>
      <button type="button" onClick={toggle}>
        Toggle theme
      </button>
      <button
        type="button"
        onClick={() => dispatch({ type: "signedIn", user: "ada" })}
      >
        Sign in
      </button>
      <button type="button" onClick={() => dispatch({ type: "messageArrived" })}>
        Simulate message
      </button>
    </>
  );
}

function Body({ onRender }: { onRender: () => void }) {
  onRender();
  const { user, unread } = useSession();
  return (
    <p>
      User: {user ?? "guest"} · Unread: {unread}
    </p>
  );
}

function Footer({ onRender }: { onRender: () => void }) {
  onRender();
  return <p>© Dojo</p>;
}

const Providers = composeProviders([ThemeProvider, SessionProvider]);

export function AppShell({
  onHeaderRender,
  onSidebarRender,
  onFooterRender,
  onBodyRender,
}: {
  onHeaderRender: () => void;
  onSidebarRender: () => void;
  onFooterRender: () => void;
  onBodyRender: () => void;
}) {
  // No state here, so these elements are created once - which is what keeps
  // the footer, a component that consumes nothing, out of every render.
  return (
    <Providers>
      <Header onRender={onHeaderRender} />
      <Sidebar onRender={onSidebarRender} />
      <Body onRender={onBodyRender} />
      <Footer onRender={onFooterRender} />
    </Providers>
  );
}

