import { createContext, useCallback, useContext, useMemo, useState } from "react";
import type { ReactNode } from "react";

export type Project = { id: string; name: string };
export type Member = { id: string; name: string };

// Split by change rate and by reader set. The draft is not here at all: it has
// exactly one reader and changes on every keystroke, so it is colocated.
const ProjectContext = createContext<Project | null>(null);
const MembersContext = createContext<Member[] | null>(null);
const ActionsContext = createContext<{ rename: (name: string) => void } | null>(
  null,
);

function useProject(): Project {
  const value = useContext(ProjectContext);
  if (value === null) throw new Error("useProject needs a WorkspaceProvider");
  return value;
}

function useMembers(): Member[] {
  const value = useContext(MembersContext);
  if (value === null) throw new Error("useMembers needs a WorkspaceProvider");
  return value;
}

function useWorkspaceActions(): { rename: (name: string) => void } {
  const value = useContext(ActionsContext);
  if (value === null) throw new Error("useWorkspaceActions needs a WorkspaceProvider");
  return value;
}

function WorkspaceProvider({
  members,
  children,
}: {
  members: Member[];
  children: ReactNode;
}) {
  const [project, setProject] = useState<Project>({ id: "p1", name: "Atlas" });

  const rename = useCallback(
    (name: string) =>
      setProject((current) => (current.name === name ? current : { ...current, name })),
    [],
  );
  // Never changes, so RenameButton is never woken by a context.
  const actions = useMemo(() => ({ rename }), [rename]);

  return (
    <ActionsContext value={actions}>
      <MembersContext value={members}>
        <ProjectContext value={project}>{children}</ProjectContext>
      </MembersContext>
    </ActionsContext>
  );
}

function TitleBar({ onRender }: { onRender: () => void }) {
  onRender();
  return <h1>{useProject().name}</h1>;
}

function MemberList({ onRender }: { onRender: () => void }) {
  onRender();
  return (
    <ul>
      {useMembers().map((member) => (
        <li key={member.id}>{member.name}</li>
      ))}
    </ul>
  );
}

function DraftEditor({ onRender }: { onRender: () => void }) {
  onRender();
  // Colocated: one reader, changing on every keystroke. It was the loudest
  // value in the old context and the reason all five consumers woke.
  const [draft, setDraft] = useState("");

  return (
    <>
      <label htmlFor="draft">Draft</label>
      <input
        id="draft"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
      />
      <p role="status">Draft length: {draft.length}</p>
    </>
  );
}

function RenameButton({ onRender }: { onRender: () => void }) {
  onRender();
  const { rename } = useWorkspaceActions();
  return (
    <button type="button" onClick={() => rename("Borealis")}>
      Rename
    </button>
  );
}

function HelpLink({ onRender }: { onRender: () => void }) {
  onRender();
  return <a href="/help">Help</a>;
}

export function WorkspaceScreen({
  members,
  onTitleRender,
  onMembersRender,
  onDraftRender,
  onRenameRender,
  onHelpRender,
}: {
  members: Member[];
  onTitleRender: () => void;
  onMembersRender: () => void;
  onDraftRender: () => void;
  onRenameRender: () => void;
  onHelpRender: () => void;
}) {
  return (
    <WorkspaceProvider members={members}>
      <TitleBar onRender={onTitleRender} />
      <MemberList onRender={onMembersRender} />
      <DraftEditor onRender={onDraftRender} />
      <RenameButton onRender={onRenameRender} />
      <HelpLink onRender={onHelpRender} />
    </WorkspaceProvider>
  );
}

