// v3ra06_composed_hooks / ex1 - reference solution.
import { memo, useCallback, useState } from "react";

/**
 * A boolean and a toggle. The toggle is stable for the life of the component,
 * so callers may safely place it in dependency arrays and pass it to memoized
 * children.
 */
export function useToggle(initial = false): [boolean, () => void] {
  const [value, setValue] = useState(initial);
  // The updater form reads nothing, so the array is honestly empty.
  const toggle = useCallback(() => setValue((current) => !current), []);
  return [value, toggle];
}

export const PanelBody = memo(function PanelBody({
  onToggle,
  onRender,
}: {
  onToggle: () => void;
  onRender: () => void;
}) {
  onRender();
  return (
    <button type="button" onClick={onToggle}>
      Toggle body
    </button>
  );
});

export function DetailsPanel({ onBodyRender }: { onBodyRender: () => void }) {
  const [open, toggle] = useToggle(false);

  return (
    <>
      <p role="status">Open: {open ? "yes" : "no"}</p>
      <button type="button" onClick={toggle}>
        Toggle panel
      </button>
      <PanelBody onToggle={toggle} onRender={onBodyRender} />
    </>
  );
}

