// v3ra06_composed_hooks / ex2 - reference solution.
import { useEffect, useRef, useState } from "react";

/** The value as of the previous commit - it moves on every re-render. */
export function usePreviousCommitted<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  // No dependency array: refreshed after every commit, which is precisely why
  // an unrelated re-render advances it.
  useEffect(() => {
    ref.current = value;
  });
  return ref.current;
}

/** The value from before the last actual change. */
export function usePreviousRendered<T>(value: T): T | undefined {
  const [previous, setPrevious] = useState<T | undefined>(undefined);
  const [current, setCurrent] = useState(value);

  // Setting state during render is legal when it targets this component and
  // the condition eventually becomes false: React discards this render's
  // output and re-runs immediately, before committing anything.
  if (!Object.is(current, value)) {
    setPrevious(current);
    setCurrent(value);
  }

  return previous;
}

export function ScoreTracker({
  score,
  label,
}: {
  score: number;
  label: string;
}) {
  const committed = usePreviousCommitted(score);
  const rendered = usePreviousRendered(score);

  return (
    <>
      <h2>{label}</h2>
      <p role="status">
        Committed: {committed ?? "none"} · Rendered: {rendered ?? "none"}
      </p>
    </>
  );
}

// v3ra06_composed_hooks / ex3 - reference solution.
import { useEffect, useRef, useState } from "react";

type Listener = (event: unknown) => void;

export type EventTargetLike = {
  addEventListener: (type: string, listener: Listener) => void;
  removeEventListener: (type: string, listener: Listener) => void;
};

/** Keeps a ref pointing at the newest value, refreshed after every commit. */
export function useLatest<T>(value: T) {
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
  });
  return ref;
}

export function useEventListener(
  target: EventTargetLike,
  type: string,
  handler: Listener,
): void {
  const latest = useLatest(handler);

  useEffect(() => {
    // One const, used for both add and remove: removeEventListener compares
    // references, so a freshly created arrow would remove nothing.
    const listener: Listener = (event) => latest.current(event);
    target.addEventListener(type, listener);
    return () => target.removeEventListener(type, listener);
    // `target` and `type` define the subscription; `handler` is only read when
    // an event happens, so it is not a dependency.
  }, [target, type, latest]);
}

export function ShortcutBar({
  target,
  onCommand,
  label,
}: {
  target: EventTargetLike;
  onCommand: (event: unknown) => void;
  label: string;
}) {
  const [commands, setCommands] = useState(0);

  useEventListener(target, "command", (event) => {
    setCommands((current) => current + 1);
    onCommand(event);
  });

  return (
    <>
      <h2>{label}</h2>
      <p role="status">Commands: {commands}</p>
    </>
  );
}

// v3ra06_composed_hooks / ex4 - reference solution.
import { useCallback, useEffect, useState } from "react";

export function useDebouncedValue<T>(
  value: T,
  delayMs: number,
): { debounced: T; isPending: boolean; flush: () => void } {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs);
    // Cancels the previous wait and cancels on unmount - one line, both jobs.
    return () => clearTimeout(id);
  }, [value, delayMs]);

  // Stable: callers put this in dependency arrays and pass it to memoized
  // children. It reads `value` through the closure of the render that created
  // it, which is exactly the value a user pressing "now" means.
  const flush = useCallback(() => setDebounced(value), [value]);

  return { debounced, isPending: !Object.is(debounced, value), flush };
}

export function SearchBox({ onSettled }: { onSettled: (query: string) => void }) {
  const [query, setQuery] = useState("");
  const { debounced, isPending, flush } = useDebouncedValue(query, 300);

  useEffect(() => {
    onSettled(debounced);
  }, [debounced, onSettled]);

  return (
    <>
      <label htmlFor="search">Search</label>
      <input
        id="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      <p role="status">{isPending ? "Waiting…" : `Settled: ${debounced}`}</p>
      <button type="button" onClick={flush}>
        Search now
      </button>
    </>
  );
}

// v3ra06_composed_hooks / ex5 - reference solution.
import { useCallback, useSyncExternalStore } from "react";

export type Storage = {
  read: (key: string) => string | null;
  write: (key: string, value: string) => void;
  subscribe: (listener: () => void) => () => void;
  reads: () => number;
};

export function createStorage(initial: Record<string, string>): Storage {
  const data = new Map(Object.entries(initial));
  const listeners = new Set<() => void>();
  let reads = 0;

  return {
    read: (key) => {
      reads += 1;
      return data.get(key) ?? null;
    },
    write: (key, value) => {
      if (data.get(key) === value) return;
      data.set(key, value);
      for (const listener of listeners) listener();
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    reads: () => reads,
  };
}

/**
 * State whose home is the storage, not the component. Two call sites with the
 * same key are two subscribers to one value, so they cannot drift.
 */
export function usePersistentState(
  storage: Storage,
  key: string,
  fallback: string,
): [string, (value: string) => void] {
  const value = useSyncExternalStore(storage.subscribe, () =>
    // A string, so the Object.is comparison is stable while nothing changes.
    storage.read(key) ?? fallback,
  );

  const setValue = useCallback(
    (next: string) => storage.write(key, next),
    [storage, key],
  );

  return [value, setValue];
}

export function ThemePicker({ storage }: { storage: Storage }) {
  const [, setTheme] = usePersistentState(storage, "theme", "day");
  return (
    <>
      <button type="button" onClick={() => setTheme("day")}>
        Day
      </button>
      <button type="button" onClick={() => setTheme("night")}>
        Night
      </button>
    </>
  );
}

export function ThemeBadge({ storage }: { storage: Storage }) {
  const [theme] = usePersistentState(storage, "theme", "day");
  return <p role="status">Theme: {theme}</p>;
}

export function SettingsScreen({ storage }: { storage: Storage }) {
  return (
    <>
      <ThemePicker storage={storage} />
      <ThemeBadge storage={storage} />
    </>
  );
}

