// v3ra06_composed_hooks / ex6 - reference solution.
import { useCallback, useEffect, useReducer } from "react";

export type AsyncState<T> =
  | { status: "idle" }
  | { status: "pending" }
  | { status: "success"; data: T }
  | { status: "failure"; message: string };

export type AsyncAction<T> =
  | { type: "started" }
  | { type: "succeeded"; data: T }
  | { type: "failed"; message: string };

// Pure, exported, and testable with values alone - no React, no timers.
export function asyncReducer<T>(
  state: AsyncState<T>,
  action: AsyncAction<T>,
): AsyncState<T> {
  switch (action.type) {
    case "started":
      return state.status === "pending" ? state : { status: "pending" };
    case "succeeded":
      return { status: "success", data: action.data };
    case "failed":
      return { status: "failure", message: action.message };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled async action: ${JSON.stringify(impossible)}`);
    }
  }
}

/**
 * Runs `run` on mount and whenever its identity changes. `run` must be stable -
 * wrap it in useCallback - or every render starts a new request.
 */
export function useAsync<T>(
  run: (signal: AbortSignal) => Promise<T>,
): AsyncState<T> & { reload: () => void } {
  const [state, dispatch] = useReducer(
    asyncReducer as (s: AsyncState<T>, a: AsyncAction<T>) => AsyncState<T>,
    { status: "idle" } as AsyncState<T>,
  );
  const [attempt, bump] = useReducer((n: number) => n + 1, 0);

  useEffect(() => {
    let ignore = false;
    const controller = new AbortController();

    dispatch({ type: "started" });

    run(controller.signal)
      .then((data) => {
        if (!ignore) dispatch({ type: "succeeded", data });
      })
      .catch((error) => {
        // An abort is something we caused; the flag covers it.
        if (!ignore) dispatch({ type: "failed", message: String(error) });
      });

    return () => {
      ignore = true;
      controller.abort();
    };
  }, [run, attempt]);

  const reload = useCallback(() => bump(), []);

  return { ...state, reload };
}

export function ProfileCard({
  userId,
  fetchProfile,
}: {
  userId: string;
  fetchProfile: (userId: string, signal: AbortSignal) => Promise<{ name: string }>;
}) {
  const run = useCallback(
    (signal: AbortSignal) => fetchProfile(userId, signal),
    [userId, fetchProfile],
  );
  const state = useAsync(run);

  const message =
    state.status === "success"
      ? `Profile: ${state.data.name}`
      : state.status === "failure"
        ? `Failed: ${state.message}`
        : "Loading…";

  return (
    <>
      <p role="status">{message}</p>
      <button type="button" onClick={state.reload}>
        Reload
      </button>
    </>
  );
}

