// v3ra06_composed_hooks / ex7 - reference solution.
import { useEffect, useRef, useState } from "react";

function useLatest<T>(value: T) {
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
  });
  return ref;
}

export type PollerOptions = {
  intervalMs: number;
  url: string;
  onResult: (result: string) => void;
  onError?: (message: string) => void;
};

/**
 * Polls `url` every `intervalMs`. Changing the interval or the url restarts
 * polling; changing the callbacks takes effect on the next tick. Safe to call
 * with an inline options object.
 */
export function usePoller(
  poll: (url: string) => Promise<string>,
  options: PollerOptions,
): { ticks: number } {
  // Primitives compare correctly; the object they came from does not.
  const { intervalMs, url } = options;
  const latest = useLatest(options);

  const [ticks, setTicks] = useState(0);

  useEffect(() => {
    let ignore = false;

    const id = setInterval(async () => {
      try {
        const result = await poll(url);
        if (ignore) return;
        setTicks((current) => current + 1);
        latest.current.onResult(result);
      } catch (error) {
        if (ignore) return;
        latest.current.onError?.(String(error));
      }
    }, intervalMs);

    return () => {
      ignore = true;
      clearInterval(id);
    };
    // The callbacks are deliberately absent: they are read when a tick
    // happens, not reacted to.
  }, [poll, url, intervalMs, latest]);

  return { ticks };
}

export function HealthPanel({
  poll,
  url,
  intervalMs,
  onResult,
  label,
}: {
  poll: (url: string) => Promise<string>;
  url: string;
  intervalMs: number;
  onResult: (result: string) => void;
  label: string;
}) {
  // A fresh object every render, on purpose: the hook is robust against it.
  const { ticks } = usePoller(poll, { url, intervalMs, onResult });

  return (
    <>
      <h2>{label}</h2>
      <p role="status">Ticks: {ticks}</p>
    </>
  );
}

// v3ra06_composed_hooks / ex8 - reference solution.
import { useState } from "react";

export type Comment = { id: string; text: string };

// The conditional state moved into its own component: mounting and unmounting
// is what "sometimes this has state" actually means.
function ReplyBox({ commentId }: { commentId: string }) {
  const [draft, setDraft] = useState("");
  const inputId = `reply-${commentId}`;

  return (
    <>
      <label htmlFor={inputId}>Reply to {commentId}</label>
      <input
        id={inputId}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
      />
    </>
  );
}

export function CommentRow({
  comment,
  showDrafts,
}: {
  comment: Comment;
  showDrafts: boolean;
}) {
  // Unconditional, at the top, exactly once per render of this fiber.
  const [expanded, setExpanded] = useState(false);

  return (
    <li>
      {comment.text}
      <button type="button" onClick={() => setExpanded((open) => !open)}>
        Toggle {comment.id}
      </button>
      {expanded && <p>Expanded {comment.id}</p>}
      {showDrafts && <ReplyBox commentId={comment.id} />}
    </li>
  );
}

export function CommentList({
  comments,
  showDrafts,
}: {
  comments: Comment[];
  showDrafts: boolean;
}) {
  // One component per item, so one fiber and one hook list per item. The key
  // is the comment's identity, not its position - reordering must carry the
  // state with the row, not leave it in the slot.
  return (
    <ul>
      {comments.map((comment) => (
        <CommentRow key={comment.id} comment={comment} showDrafts={showDrafts} />
      ))}
    </ul>
  );
}

export function CommentScreen({
  comments,
  showDrafts,
}: {
  comments: Comment[];
  showDrafts: boolean;
}) {
  return <CommentList comments={comments} showDrafts={showDrafts} />;
}

