// v3ra06_composed_hooks / challenge - reference solution.
import { useCallback, useEffect, useReducer, useState } from "react";

export type Row = { id: string; label: string };

export function useDebouncedValue<T>(
  value: T,
  delayMs: number,
): { debounced: T } {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delayMs);
    return () => clearTimeout(id);
  }, [value, delayMs]);

  return { debounced };
}

type AsyncState<T> =
  | { status: "idle" }
  | { status: "pending" }
  | { status: "success"; data: T }
  | { status: "failure"; message: string };

type AsyncAction<T> =
  | { type: "reset" }
  | { type: "started" }
  | { type: "succeeded"; data: T }
  | { type: "failed"; message: string };

function asyncReducer<T>(
  state: AsyncState<T>,
  action: AsyncAction<T>,
): AsyncState<T> {
  switch (action.type) {
    case "reset":
      return state.status === "idle" ? state : { status: "idle" };
    case "started":
      return state.status === "pending" ? state : { status: "pending" };
    case "succeeded":
      return { status: "success", data: action.data };
    case "failed":
      return { status: "failure", message: action.message };
    default: {
      const impossible: never = action;
      throw new Error(`Unhandled async action: ${JSON.stringify(impossible)}`);
    }
  }
}

/** Knows nothing about debouncing. `run` must be stable, or null for "no job". */
export function useAsync<T>(
  run: ((signal: AbortSignal) => Promise<T>) | null,
): AsyncState<T> {
  const [state, dispatch] = useReducer(
    asyncReducer as (s: AsyncState<T>, a: AsyncAction<T>) => AsyncState<T>,
    { status: "idle" } as AsyncState<T>,
  );

  useEffect(() => {
    if (run === null) {
      dispatch({ type: "reset" });
      return;
    }

    let ignore = false;
    const controller = new AbortController();

    dispatch({ type: "started" });

    run(controller.signal)
      .then((data) => {
        if (!ignore) dispatch({ type: "succeeded", data });
      })
      .catch((error) => {
        // The flag covers the abort we caused, so it is never a failure.
        if (!ignore) dispatch({ type: "failed", message: String(error) });
      });

    return () => {
      ignore = true;
      controller.abort();
    };
  }, [run]);

  return state;
}

export function useSearch(
  query: string,
  search: (query: string, signal: AbortSignal) => Promise<Row[]>,
): {
  status: AsyncState<Row[]>["status"];
  rows: Row[];
  message: string | null;
} {
  const { debounced } = useDebouncedValue(query.trim(), 300);

  const run = useCallback(
    (signal: AbortSignal) => search(debounced, signal),
    [debounced, search],
  );

  // The empty-query rule lives here, in the composition, so neither hook has
  // to know about it.
  const state = useAsync(debounced === "" ? null : run);

  return {
    status: state.status,
    rows: state.status === "success" ? state.data : [],
    message: state.status === "failure" ? state.message : null,
  };
}

export function SearchScreen({
  search,
}: {
  search: (query: string, signal: AbortSignal) => Promise<Row[]>;
}) {
  const [query, setQuery] = useState("");
  const { status, rows } = useSearch(query, search);

  const message =
    status === "idle"
      ? "Type to search"
      : status === "pending"
        ? "Searching…"
        : status === "failure"
          ? "Search failed"
          : `Results: ${rows.length}`;

  return (
    <>
      <label htmlFor="search">Search</label>
      <input
        id="search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      <p role="status">{message}</p>
      <ul>
        {rows.map((row) => (
          <li key={row.id}>{row.label}</li>
        ))}
      </ul>
    </>
  );
}

