// v3ra06_composed_hooks / review1 - reference solution.
import { memo, useCallback, useEffect, useMemo, useState } from "react";

export type Connection = {
  onStatus: (listener: (status: string) => void) => void;
  disconnect: () => void;
};
export type Connect = (roomId: string) => Connection;

export function useConnection(connect: Connect, roomId: string, retries: number) {
  const [status, setStatus] = useState("offline");
  const [attempts, setAttempts] = useState(0);

  useEffect(() => {
    // Fault 1: the cleanup closes over the connection this run created, so a
    // room change disconnects the old one before opening the new one - and a
    // leak here would have been replicated at every call site.
    const connection = connect(roomId);
    connection.onStatus(setStatus);
    return () => connection.disconnect();
  }, [connect, roomId]);

  // Fault 3: the updater form reads nothing, so the array is honestly empty
  // and the callback is not rebuilt by the event it exists to handle.
  const retry = useCallback(() => {
    setStatus("offline");
    setAttempts((current) => current + 1);
  }, []);

  // Fault 2: stabilise the leaves before the root, or the outer memo changes
  // on every render anyway.
  const limits = useMemo(() => ({ retries }), [retries]);

  return useMemo(
    () => ({ status, attempts, retry, limits }),
    [status, attempts, retry, limits],
  );
}

export const ConnectionView = memo(function ConnectionView({
  status,
  attempts,
  onRetry,
  onRender,
}: {
  status: string;
  attempts: number;
  onRetry: () => void;
  onRender: () => void;
}) {
  onRender();
  return (
    <>
      <p role="status">Status: {status}</p>
      <p>Attempts: {attempts}</p>
      <button type="button" onClick={onRetry}>
        Retry
      </button>
    </>
  );
});

export function ConnectionBadge({
  connect,
  roomId,
  retries,
  onRender,
}: {
  connect: Connect;
  roomId: string;
  retries: number;
  onRender: () => void;
}) {
  const { status, attempts, retry } = useConnection(connect, roomId, retries);

  return (
    <ConnectionView
      status={status}
      attempts={attempts}
      onRetry={retry}
      onRender={onRender}
    />
  );
}
